// Ambient wildlife (2026-09-26): deer herds with a stag, and lone foxes, that
// graze and wander around a home meadow and bolt when you get close. Purely
// scenery - no interaction, not saved - and they respect water and ridges.
struct WildAnimal { int id; Vector2 home, pos, target; float timer, fleeT, speed; bool placed; };
static std::vector<WildAnimal> g_wildAnimals;
static void WildAnimalsEnsure() {
    static bool built = false;
    if (built) return;
    built = true;
    WildTerrainEnsure();
    struct Home { float x, z; bool herd; };
    static const Home homes[] = {
        { 1250, 2230, true }, { 620, 2640, true }, { 1950, 2950, true }, { 2600, 700, true }, { 1200, 3000, true },
        { 1500, 1500, false }, { 2400, 2950, false }, { 380, 2950, false }, { 2850, 950, false }, { 800, 1300, false },
    };
    auto clearOfGameplay = [](Vector2 p) {
        for (const auto& m : kWildernessMonsterSpots) if (hypotf(p.x - m.pos.x, p.y - m.pos.y) < 170.0f) return false;
        for (const auto& g : kTownGates) if (hypotf(p.x - g.wildernessPos.x, p.y - g.wildernessPos.y) < 200.0f) return false;
        return true;
    };
    for (const Home& h : homes) {
        Vector2 home = WildNearestFree({ h.x, h.z });
        if (WildBlocked(home) || !clearOfGameplay(home)) continue;
        int n = h.herd ? 4 : 1;
        for (int k = 0; k < n; k++) {
            WildAnimal a{};
            a.id = h.herd ? (k == 0 ? kAnStag : kAnDeer) : kAnFox;
            a.home = home;
            float ang = k * 1.9f + h.x * 0.01f;
            a.pos = WildNearestFree({ home.x + cosf(ang) * 40.0f * k, home.y + sinf(ang) * 40.0f * k });
            a.target = a.pos;
            a.timer = 1.0f + k * 1.3f;
            g_wildAnimals.push_back(a);
        }
    }
}
static void WildAnimalsUpdateDraw(const GameState& s, const Town3DCam* cull, bool shadowPass) {
    WildAnimalsEnsure();
    float dt = shadowPass ? 0.0f : GameDt();
    int idx = 0;
    for (WildAnimal& a : g_wildAnimals) {
        idx++;
        float dxp = s.wildernessPlayerPos.x - a.pos.x, dzp = s.wildernessPlayerPos.y - a.pos.y;
        float dp = hypotf(dxp, dzp);
        bool shy = !s.playerIsGhost && dp < (a.id == kAnFox ? 150.0f : 190.0f);
        if (shy && a.fleeT <= 0.0f) { // bolt directly away, but stay near home
            a.fleeT = 2.4f;
            Vector2 away = { -dxp / std::max(1.0f, dp), -dzp / std::max(1.0f, dp) };
            a.target = { a.pos.x + away.x * 260.0f, a.pos.y + away.y * 260.0f };
            float hx = a.target.x - a.home.x, hz = a.target.y - a.home.y, hd = hypotf(hx, hz);
            if (hd > 420.0f) { a.target.x = a.home.x + hx / hd * 420.0f; a.target.y = a.home.y + hz / hd * 420.0f; }
        }
        a.fleeT -= dt;
        a.timer -= dt;
        if (a.fleeT <= 0.0f && a.timer <= 0.0f) { // new graze spot near home
            float h1 = Town3DHash01((float)idx * 7.1f, s.worldTime * 0.37f);
            float h2 = Town3DHash01(s.worldTime * 0.53f, (float)idx * 3.3f);
            a.target = { a.home.x + (h1 - 0.5f) * 320.0f, a.home.y + (h2 - 0.5f) * 320.0f };
            a.timer = 3.0f + 5.0f * h1;
        }
        float want = (a.fleeT > 0.0f) ? 200.0f : 38.0f;
        float tx = a.target.x - a.pos.x, tz = a.target.y - a.pos.y, td = hypotf(tx, tz);
        float spd = (td > 6.0f) ? want : 0.0f;
        a.speed += (spd - a.speed) * std::min(1.0f, dt * 5.0f);
        if (td > 1.0f && a.speed > 1.0f) {
            Vector2 prev = a.pos;
            float step = std::min(td, a.speed * dt);
            a.pos.x += tx / td * step; a.pos.y += tz / td * step;
            if (WildBlocked(a.pos)) { a.pos = prev; a.target = prev; a.fleeT = 0.0f; } // shore/ridge: stop and graze
        }
        if (cull && !Wild3DInView(*cull, a.pos.x, a.pos.y, 60.0f)) continue;
        float yaw = atan2f(tz, tx);
        if (td < 2.0f) yaw = Town3DHash01((float)idx, 1.7f) * 6.2832f;
        AnimalPose ap;
        ap.move = std::clamp(a.speed / 200.0f * (a.speed > 60.0f ? 1.0f : 0.5f), 0.0f, 1.0f);
        ap.time = s.worldTime + idx * 0.61f;
        ap.track = 1000 + idx;
        DrawAnimal(a.id, a.pos.x, a.pos.y, yaw, 1.0f, WHITE, ap, shadowPass);
    }
}

// Town surroundings (2026-09-26): instead of flat green forever past the town
// edge, draw the actual wilderness around this town's gate - ground (roads,
// rivers, coast, region colors), scenery, bridges, sea - offset so the town's
// Wilderness Gate sits on its gate in the wilderness and the roads visibly run
// out of town. Anything that would land inside the town is skipped.
static Vector2 TownWildOffset(int townIdx) { // wilderness = town + offset
    Vector2 g = kTownGates[std::clamp(townIdx, 0, (int)kTownGates.size() - 1)].wildernessPos;
    return { g.x - kWildernessGatePos.x, g.y - kWildernessGatePos.y };
}
static void Town3DDrawSurroundings(const GameState& s, const Town3DCam& c) {
    Wild3DLoadModels();
    Wild3DEnsureGround();
    Wild3DBuildDressing();
    static bool bridgesBuilt = false; // shares Wild3DDrawDressing's build flag semantics
    if (!bridgesBuilt && g_wildBridgeModels.empty()) { bridgesBuilt = true; Wild3DBuildBridges(); }
    Vector2 O = TownWildOffset(s.selectedTown);
    // Just under the town's own ground plane (y=0), so the town covers it.
    DrawModel(g_wild3dGround.model, { -O.x, -0.8f, -O.y }, 1.0f, WHITE); // world-coordinate mesh, shifted into town space
    DrawPlane({ 5600.0f - O.x, -2.5f, 1600.0f - O.y }, { 4800, 8000 }, Color{ 44, 96, 122, 255 }); // open sea
    auto outsideTown = [](float x, float z, float r) {
        return x < -r || z < -r || x > kTownWorldSize + r || z > kTownWorldSize + r;
    };
    const Wild3DDressing& D = g_wild3dDress;
    for (const WildDressItem& it : D.items) {
        float x = it.x - O.x, z = it.z - O.y;
        if (!outsideTown(x, z, 40.0f + it.cullR * 0.5f)) continue;
        if (!Wild3DInView(c, x, z, it.cullR)) continue;
        DrawModelEx(D.models[it.id], { x, WildGroundY(it.x, it.z) - 0.8f, z }, { 0.0f, 1.0f, 0.0f }, it.rot, { it.scale, it.scale, it.scale }, it.tint);
    }
    for (const WildBridgeModel& m : g_wildBridgeModels) {
        float x = m.cx - O.x, z = m.cz - O.y;
        if (!outsideTown(x, z, m.len * 0.6f) || !Wild3DInView(c, x, z, m.len * 0.6f + 30.0f)) continue;
        DrawModelEx(m.model, { x, 0.0f, z }, { 0.0f, 1.0f, 0.0f }, m.yawDeg, { 1.0f, 1.0f, 1.0f }, WHITE);
    }
}

// ---- Corpse bodies (2026-09-26) ----
static const int kT3CTrackCorpse = 400; // + corpse id % 64: own animation state per body
static void CorpseDrawMound(const GameState::WorldCorpse& c) {
    T3DLiftScope lift_(c.pos.x, c.pos.y);
    DrawCylinderEx({ c.pos.x, 0.5f, c.pos.y }, { c.pos.x, 1.5f, c.pos.y }, 22.0f, 22.0f, 12, Color{ 70, 30, 26, 200 }); // blood
    DrawSphereEx({ c.pos.x, 5.0f, c.pos.y }, 15.0f, 8, 6, Color{ 60, 50, 46, 255 });
}
// Gold glint + ground ring over a body that still has something on it.
static void CorpseDrawGlint(const GameState::WorldCorpse& c) {
    if (!c.Lootable()) return;
    T3DLiftScope lift_(c.pos.x, c.pos.y);
    float t = (float)g_gameClock;
    float pulse = 0.55f + 0.45f * sinf(t * 3.0f + c.id);
    DrawCircle3D({ c.pos.x, 1.5f, c.pos.y }, 26.0f + 2.0f * pulse, { 1, 0, 0 }, 90.0f, Fade(Color{ 255, 210, 90, 255 }, 0.55f * pulse));
    float y = 30.0f + 3.0f * sinf(t * 2.2f + c.id);
    DrawSphereEx({ c.pos.x, y, c.pos.y }, 3.2f, 6, 6, Fade(Color{ 255, 226, 120, 255 }, 0.8f + 0.2f * pulse));
}
static void Wild3DDrawCorpse(const GameState::WorldCorpse& c, bool shadowPass) {
    float sink = c.timer < 10.0f ? (1.0f - c.timer / 10.0f) * 26.0f : 0.0f;
    rlPushMatrix();
    rlTranslatef(0.0f, -sink, 0.0f);
    int track = kT3CTrackCorpse + c.id % 64;
    const Color dim = { 190, 180, 175, 255 };
    HumanPose dead; dead.deathT = 1.0f;
    bool drawn = false;
    if (c.isRival) drawn = DrawHuman(track, c.pos.x, c.pos.y, c.yaw, 1.02f, dim, HumanOutfitRival(), dead, shadowPass);
    else if (c.bladeIdx >= 0) drawn = DrawHuman(track, c.pos.x, c.pos.y, c.yaw, 0.95f, dim, HumanOutfitBlade(), dead, shadowPass);
    else if (c.spotIdx >= 0 && c.spotIdx < (int)kWildernessMonsterSpots.size()) {
        const WildernessMonsterSpot& sp = kWildernessMonsterSpots[c.spotIdx];
        T3CMonLook ml = T3CMonsterLook(sp.iconIdx);
        Color rc = { 0, 0, 0, 0 }; float sc = 1.0f;
        int an = ml.humanoid ? -1 : AnimalForMonster(sp.iconIdx, &rc, &sc);
        if (an >= 0) {
            AnimalPose ap; ap.recolor = rc; ap.deathT = 1.0f; // lying where it fell
            Color named = AnimalRecolorForMonsterName(sp.name);
            if (named.a > 0) ap.recolor = named;
            drawn = DrawAnimal(an, c.pos.x, c.pos.y, c.yaw, sc, dim, ap, shadowPass);
        } else if (ml.humanoid) {
            drawn = DrawHuman(track, c.pos.x, c.pos.y, c.yaw, ml.scale * 0.94f, dim,
                              HumanOutfitForWildMonster(sp.iconIdx, sp.name, ml), dead, shadowPass);
        }
    }
    if (!drawn && !shadowPass) CorpseDrawMound(c);
    rlPopMatrix();
    if (!shadowPass) CorpseDrawGlint(c);
}
// ---- Murder Inc.'s war camp (2026-09-27) --------------------------------------------
// Where the guild musters between hunts: a ring palisade of sharpened stakes with
// a gate and two watchtowers, the champion's command tent under banners, a row
// of soldiers' tents, a central campfire, training dummies, weapon racks and
// supplies - and a few recruits drilling, standing sentry and warming their
// hands. The gate faces the middle of the map. Built once per camp site.
static const Texture2D& GlowTex();                                  // (with the room surfaces)
static void GlowPool(float x, float z, float y, float r, Color c);
static const float kCampRadius = 170.0f;
static float RivalCampGateYaw(Vector2 c) { return atan2f(1600.0f - c.y, 1600.0f - c.x); } // gate direction
static bool RivalCampInGate(Vector2 c, Vector2 p) {
    float a = atan2f(p.y - c.y, p.x - c.x) - RivalCampGateYaw(c);
    a = atan2f(sinf(a), cosf(a));
    return fabsf(a) < 0.26f;
}
// The palisade stops you (and only you - the guild comes and goes through it).
static void RivalCampResolve(const GameState& s, Vector2& p, float r) {
    Vector2 c = kRivalCampSpots[s.rivalCampIdx];
    float d = Dist(p, c);
    if (d < 1.0f || fabsf(d - kCampRadius) > r + 6.0f || RivalCampInGate(c, p)) return;
    float want = d < kCampRadius ? kCampRadius - r - 6.0f : kCampRadius + r + 6.0f;
    p = { c.x + (p.x - c.x) / d * want, c.y + (p.y - c.y) / d * want };
}
// Grimtusk Hold's palisade: a ring you can only cross at the gate.
static void OrcFortResolve(Vector2& p, float r) {
    const Vector2 c = kOrcFortPos;
    const float wallR = kOrcFortRadius + 4.0f;
    float d = Dist(p, c);
    if (d < 1.0f || fabsf(d - wallR) > r + 10.0f) return;
    float a = atan2f(p.y - c.y, p.x - c.x) - kOrcFortGateYaw;
    if (fabsf(atan2f(sinf(a), cosf(a))) < 0.15f) return; // the gateway
    float want = d < wallR ? wallR - r - 10.0f : wallR + r + 10.0f;
    p = { c.x + (p.x - c.x) / d * want, c.y + (p.y - c.y) / d * want };
}
struct RivalCampModel { bool built = false; Model m{}; };
static RivalCampModel g_campModels[5];
static void RivalCampBuild(int idx) {
    RivalCampModel& cm = g_campModels[idx];
    if (cm.built) return;
    cm.built = true;
    Vector2 c = kRivalCampSpots[idx];
    float gate = RivalCampGateYaw(c);
    T3CMeshBuilder b;
    const Color log = { 112, 80, 52, 255 }, logDk = { 84, 60, 40, 255 }, tip = { 150, 120, 86, 255 }, rope = { 170, 150, 110, 255 };
    // palisade stakes
    int n = (int)(6.2832f * kCampRadius / 9.0f);
    for (int i = 0; i < n; i++) {
        float a = gate + 6.2832f * i / n;
        float rel = atan2f(sinf(a - gate), cosf(a - gate));
        if (fabsf(rel) < 0.2f) continue; // the gateway
        float h = 44.0f + Town3DHash01((float)i, (float)idx) * 12.0f;
        float x = cosf(a) * kCampRadius, z = sinf(a) * kCampRadius;
        T3CCylinder(b, x, 0.0f, z, h, 4.6f, 4.2f, 6, (i % 3) ? log : logDk, false, false);
        T3CCylinder(b, x, h, z, h + 9.0f, 4.2f, 0.3f, 6, tip, false, false);
    }
    // two rope/beam bindings round the wall
    for (int ring = 0; ring < 2; ring++) {
        float y = 16.0f + ring * 20.0f;
        for (int i = 0; i < n; i++) {
            float a0 = gate + 6.2832f * i / n, a1 = gate + 6.2832f * (i + 1) / n;
            float rel = atan2f(sinf(a0 - gate), cosf(a0 - gate)), rel1 = atan2f(sinf(a1 - gate), cosf(a1 - gate));
            if (fabsf(rel) < 0.2f || fabsf(rel1) < 0.2f) continue;
            float r = kCampRadius + 4.5f;
            float p0[3] = { cosf(a0) * r, y, sinf(a0) * r }, p1[3] = { cosf(a1) * r, y, sinf(a1) * r };
            float p2[3] = { p1[0], y + 2.5f, p1[2] }, p3[3] = { p0[0], y + 2.5f, p0[2] };
            T3CQuad(b, p0, p1, p2, p3, rope);
        }
    }
    // gate towers: four posts, a platform, a railing, a little roof
    for (int side = -1; side <= 1; side += 2) {
        float a = gate + side * 0.27f;
        float tx = cosf(a) * kCampRadius, tz = sinf(a) * kCampRadius;
        for (int px = -1; px <= 1; px += 2)
            for (int pz = -1; pz <= 1; pz += 2) T3CBox(b, tx + px * 9.0f, 42.0f, tz + pz * 9.0f, 4.5f, 84.0f, 4.5f, logDk);
        T3CBox(b, tx, 66.0f, tz, 24.0f, 3.0f, 24.0f, log);
        for (int k = 0; k < 4; k++) {
            float ox = (k < 2 ? (k == 0 ? -1 : 1) * 11.0f : 0.0f), oz = (k >= 2 ? (k == 2 ? -1 : 1) * 11.0f : 0.0f);
            T3CBox(b, tx + ox, 74.0f, tz + oz, k < 2 ? 2.5f : 24.0f, 12.0f, k < 2 ? 24.0f : 2.5f, log);
        }
        float r0[3] = { tx - 14, 86, tz - 14 }, r1[3] = { tx + 14, 86, tz - 14 }, r2[3] = { tx + 14, 86, tz + 14 }, r3[3] = { tx - 14, 86, tz + 14 };
        float apex[3] = { tx, 100, tz };
        T3CPushTri(b, r0, r1, apex, Color{ 120, 36, 34, 255 }); T3CPushTri(b, r1, r2, apex, Color{ 104, 30, 30, 255 });
        T3CPushTri(b, r2, r3, apex, Color{ 120, 36, 34, 255 }); T3CPushTri(b, r3, r0, apex, Color{ 104, 30, 30, 255 });
    }
    // campfire ring and logs
    for (int i = 0; i < 9; i++) {
        float a = 6.2832f * i / 9;
        T3CSphere(b, cosf(a) * 14.0f, 2.0f, sinf(a) * 14.0f, 4.5f, 3.2f, 4.5f, 5, 6, Color{ 110, 106, 100, 255 });
    }
    for (int i = 0; i < 3; i++) {
        float a = 1.0f + i * 2.1f;
        float p0[3] = { cosf(a) * 10.0f, 2.0f, sinf(a) * 10.0f }, dir[3] = { -cosf(a), 0.45f, -sinf(a) };
        (void)p0; (void)dir;
        T3CBox(b, cosf(a) * 5.0f, 3.0f, sinf(a) * 5.0f, 12.0f, 3.0f, 3.0f, logDk);
    }
    // log benches round the fire
    for (int i = 0; i < 3; i++) {
        float a = 0.6f + i * 2.1f;
        float x = cosf(a) * 36.0f, z = sinf(a) * 36.0f;
        T3CBox(b, x, 4.0f, z, 26.0f, 7.0f, 7.0f, log);
    }
    // training dummies: post, arms, straw body, sack head
    for (int i = 0; i < 2; i++) {
        float a = gate + 0.85f + i * 0.35f;
        float x = cosf(a) * 105.0f, z = sinf(a) * 105.0f;
        T3CBox(b, x, 22.0f, z, 4.0f, 44.0f, 4.0f, logDk);
        T3CBox(b, x, 34.0f, z, 26.0f, 3.5f, 3.5f, logDk);
        T3CCylinder(b, x, 18.0f, z, 36.0f, 7.0f, 6.0f, 8, Color{ 196, 170, 100, 255 });
        T3CSphere(b, x, 43.0f, z, 6.0f, 6.5f, 6.0f, 6, 8, Color{ 180, 160, 120, 255 });
    }
    // the muster ground: a trampled earth disc
    for (int i = 0; i < 24; i++) {
        float a0 = 6.2832f * i / 24, a1 = 6.2832f * (i + 1) / 24, r = kCampRadius - 12.0f;
        float o[3] = { 0, 0.35f, 0 }, p0[3] = { cosf(a0) * r, 0.35f, sinf(a0) * r }, p1[3] = { cosf(a1) * r, 0.35f, sinf(a1) * r };
        T3CPushTri(b, o, p1, p0, Color{ 122, 104, 78, 255 });
    }
    cm.m = T3CFinish(b);
    Town3DApplyLitShader(cm.m);
}

static void Wild3DDrawRivalCamp(GameState& s, bool shadowPass, const Town3DCam* cull) {
    Vector2 c = kRivalCampSpots[s.rivalCampIdx];
    if (cull && !Wild3DInView(*cull, c.x, c.y, kCampRadius + 60.0f)) return;
    RivalCampBuild(s.rivalCampIdx);
    float gate = RivalCampGateYaw(c);
    float gy = GroundY(c.x, c.y);
    DrawModel(g_campModels[s.rivalCampIdx].m, { c.x, gy, c.y }, 1.0f, WHITE);
    // KayKit camp props (the same pack as the roadside camps)
    Wild3DBuildDressing();
    const Wild3DDressing& D = g_wild3dDress;
    auto prop = [&](int id, float ang, float rad, float faceDeg, float sc, Color tint = WHITE) {
        if (!D.ok[id]) return;
        float x = c.x + cosf(gate + ang) * rad, z = c.y + sinf(gate + ang) * rad;
        DrawModelEx(D.models[id], { x, GroundY(x, z), z }, { 0, 1, 0 }, faceDeg, { sc, sc, sc }, tint);
    };
    float gateDeg = -gate * RAD2DEG;
    // command tent at the back under the banners, soldiers' tents in two rows
    prop(kWPTent, 3.1416f, 118.0f, gateDeg + 90.0f, kWPScaleProp * 1.2f, Color{ 200, 120, 110, 255 });
    prop(kWPFlagRed, 3.1416f - 0.42f, 118.0f, gateDeg, kWPScaleProp * 1.3f);
    prop(kWPFlagRed, 3.1416f + 0.42f, 118.0f, gateDeg, kWPScaleProp * 1.3f);
    const float tentA[6] = { 2.05f, 2.45f, -2.05f, -2.45f, 1.6f, -1.6f };
    for (int i = 0; i < 6; i++) prop(kWPTent, tentA[i], 120.0f, gateDeg + 90.0f - tentA[i] * RAD2DEG, kWPScaleProp * 0.8f, Color{ 170, 150, 140, 255 });
    prop(kWPFlagRed, 0.36f, kCampRadius + 2.0f, gateDeg, kWPScaleProp * 1.1f);
    prop(kWPFlagRed, -0.36f, kCampRadius + 2.0f, gateDeg, kWPScaleProp * 1.1f);
    // arms and supplies
    prop(kWPWeaponRack, 0.95f, 60.0f, gateDeg + 60.0f, kWPScaleProp);
    prop(kWPWeaponRack, -0.95f, 60.0f, gateDeg - 60.0f, kWPScaleProp);
    prop(kWPCrateBig, 2.75f, 70.0f, 20.0f, kWPScaleProp);
    prop(kWPCrateSmall, 2.9f, 58.0f, 60.0f, kWPScaleProp);
    prop(kWPBarrel, -2.8f, 66.0f, 0.0f, kWPScaleProp);
    prop(kWPBarrel, -2.95f, 56.0f, 40.0f, kWPScaleProp);
    prop(kWPSack, -2.6f, 74.0f, 10.0f, kWPScaleProp);
    prop(kWPCrateLong, 1.2f, 140.0f, gateDeg, kWPScaleProp);
    prop(kWPLumber, -1.25f, 140.0f, gateDeg, kWPScaleProp);
    // recruits: two gate sentries, one drilling at a dummy, one warming by the fire
    if (!shadowPass || true) {
        float t = (float)GetTime();
        HumanOutfit o = HumanOutfitBlade();
        o.helm = kHhPlate; o.helmCol = Color{ 110, 104, 100, 255 };
        for (int side = -1; side <= 1; side += 2) {
            float a = gate + side * 0.12f, r = kCampRadius + 14.0f;
            HumanOutfit g = o;
            HumanGive(g, kHwHalberd, kHsPolearm);
            HumanPose hp; hp.engaged = true;
            float x = c.x + cosf(a) * r, z = c.y + sinf(a) * r;
            DrawHuman(200 + (side > 0), x, z, gate, 1.0f, WHITE, g, hp, shadowPass);
        }
        {
            float a = gate + 0.85f;
            float dx = c.x + cosf(a) * 80.0f, dz = c.y + sinf(a) * 80.0f;
            float face = atan2f(sinf(a) * 105.0f - sinf(a) * 80.0f, cosf(a) * 105.0f - cosf(a) * 80.0f);
            HumanOutfit d = HumanOutfitBlade();
            HumanPose hp; hp.engaged = true;
            float ph = fmodf(t, 1.6f);
            hp.attackT = ph < 0.8f ? ph / 0.8f : -1.0f;
            DrawHuman(202, dx, dz, face, 1.0f, WHITE, d, hp, shadowPass);
        }
        {
            float a = 0.6f + 2.1f;
            float x = c.x + cosf(a) * 30.0f, z = c.y + sinf(a) * 30.0f;
            HumanOutfit f = HumanOutfitBlade();
            f.cloakCol = Color{ 70, 30, 30, 255 };
            HumanPose hp;
            DrawHuman(203, x, z, atan2f(c.y - z, c.x - x), 1.0f, WHITE, f, hp, shadowPass);
        }
    }
    if (shadowPass) return;
    // fire, torch flames at the towers, smoke
    float t = (float)GetTime(), night = g_t3dNight;
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    auto flame = [&](float x, float y, float z, float r, float k) {
        float fl = 0.8f + 0.2f * sinf(t * 11.0f + x) * sinf(t * 4.3f + z);
        rlSetTexture(GlowTex().id);
        rlBegin(RL_QUADS);
        float rr = r * fl;
        rlColor4ub((unsigned char)(255 * k), (unsigned char)(150 * k), (unsigned char)(60 * k), 255);
        rlTexCoord2f(0, 0); rlVertex3f(x - rr, y - rr, z); rlTexCoord2f(1, 0); rlVertex3f(x + rr, y - rr, z);
        rlTexCoord2f(1, 1); rlVertex3f(x + rr, y + rr, z); rlTexCoord2f(0, 1); rlVertex3f(x - rr, y + rr, z);
        rlTexCoord2f(0, 0); rlVertex3f(x, y - rr, z - rr); rlTexCoord2f(1, 0); rlVertex3f(x, y - rr, z + rr);
        rlTexCoord2f(1, 1); rlVertex3f(x, y + rr, z + rr); rlTexCoord2f(0, 1); rlVertex3f(x, y + rr, z - rr);
        rlEnd();
        rlSetTexture(0);
    };
    flame(c.x, gy + 12.0f, c.y, 16.0f, 1.0f);
    flame(c.x, gy + 7.0f, c.y, 26.0f, 0.55f);
    GlowPool(c.x, c.y, gy + 0.8f, 60.0f + 50.0f * night, Color{ (unsigned char)(120 + 100 * night), (unsigned char)(70 + 50 * night), 30, 255 });
    for (int side = -1; side <= 1; side += 2) {
        float a = gate + side * 0.27f;
        float tx = c.x + cosf(a) * (kCampRadius + 16.0f), tz = c.y + sinf(a) * (kCampRadius + 16.0f);
        flame(tx, gy + 66.0f, tz, 8.0f, 0.5f + 0.5f * night);
    }
    rlEnableDepthMask();
    EndBlendMode();
    BeginBlendMode(BLEND_ALPHA);
    rlSetTexture(GlowTex().id);
    rlBegin(RL_QUADS);
    for (int i = 0; i < 7; i++) {
        float ph = fmodf(t * 0.2f + i / 7.0f, 1.0f);
        Vector3 p = { c.x + ph * 30.0f + sinf(t + i) * 4.0f, gy + 20.0f + ph * 110.0f, c.y + ph * 12.0f };
        float r = 7.0f + ph * 22.0f;
        unsigned char a = (unsigned char)(100 * (1.0f - ph) * std::min(1.0f, ph * 8.0f));
        unsigned char v = (unsigned char)(150 - 60 * night);
        rlColor4ub(v, v, v, a);
        rlTexCoord2f(0, 0); rlVertex3f(p.x - r, p.y - r, p.z); rlTexCoord2f(1, 0); rlVertex3f(p.x + r, p.y - r, p.z);
        rlTexCoord2f(1, 1); rlVertex3f(p.x + r, p.y + r, p.z); rlTexCoord2f(0, 1); rlVertex3f(p.x - r, p.y + r, p.z);
    }
    rlEnd();
    rlSetTexture(0);
    EndBlendMode();
}
// ---- Grimtusk Hold, the orc fortress (2026-09-27) ------------------------------------
// Rougher and meaner than the Murder Inc. camp: a double ring of dark, red-tipped
// logs with outward stakes, a gatehouse crowned with a horned skull between two
// watchtowers, hide huts, the Warlord's longhouse at the back, a great bonfire, a
// war drum, skull totems and bone piles. The orcs themselves are ordinary monster
// spots (kWildernessMonsterSpots "Orc ...") drawn by the monster pass.
// A leaning stake from p0 to p1 (a four-sided prism tapering to a point).
static void T3CStake(T3CMeshBuilder& b, Vector3 p0, Vector3 p1, float r, Color col) {
    Vector3 d = { p1.x - p0.x, p1.y - p0.y, p1.z - p0.z };
    float l = sqrtf(d.x * d.x + d.y * d.y + d.z * d.z);
    if (l < 1e-3f) return;
    d = { d.x / l, d.y / l, d.z / l };
    Vector3 a = fabsf(d.y) < 0.9f ? Vector3{ 0, 1, 0 } : Vector3{ 1, 0, 0 };
    Vector3 u = { d.y * a.z - d.z * a.y, d.z * a.x - d.x * a.z, d.x * a.y - d.y * a.x };
    float ul = sqrtf(u.x * u.x + u.y * u.y + u.z * u.z); u = { u.x / ul, u.y / ul, u.z / ul };
    Vector3 v = { d.y * u.z - d.z * u.y, d.z * u.x - d.x * u.z, d.x * u.y - d.y * u.x };
    float tip[3] = { p1.x, p1.y, p1.z };
    float base[4][3];
    for (int k = 0; k < 4; k++) {
        float an = k * 1.5708f;
        base[k][0] = p0.x + (u.x * cosf(an) + v.x * sinf(an)) * r;
        base[k][1] = p0.y + (u.y * cosf(an) + v.y * sinf(an)) * r;
        base[k][2] = p0.z + (u.z * cosf(an) + v.z * sinf(an)) * r;
    }
    for (int k = 0; k < 4; k++) T3CPushTri(b, base[k], base[(k + 1) % 4], tip, k % 2 ? col : ColorBrightness(col, -0.12f));
}
static void T3CSkull(T3CMeshBuilder& b, float x, float y, float z, float s, float yaw, bool horns) {
    const Color bone = { 226, 218, 196, 255 }, hole = { 30, 24, 22, 255 }, horn = { 190, 176, 140, 255 };
    float fx = cosf(yaw), fz = sinf(yaw), sx = -fz, sz = fx;
    T3CSphere(b, x, y, z, 7 * s, 7.5f * s, 7 * s, 6, 8, bone);
    T3CBox(b, x + fx * 3 * s, y - 6 * s, z + fz * 3 * s, 8 * s, 4 * s, 8 * s, bone); // jaw
    for (int e = -1; e <= 1; e += 2)
        T3CSphere(b, x + fx * 6 * s + sx * e * 2.8f * s, y + 1 * s, z + fz * 6 * s + sz * e * 2.8f * s, 2 * s, 2.2f * s, 2 * s, 4, 6, hole);
    if (horns)
        for (int e = -1; e <= 1; e += 2)
            T3CStake(b, { x + sx * e * 5 * s, y + 4 * s, z + sz * e * 5 * s }, { x + sx * e * 16 * s, y + 14 * s, z + sz * e * 16 * s }, 2.4f * s, horn);
}
static bool g_orcFortBuilt = false;
static Model g_orcFortModel{};
static void OrcFortBuild() {
    if (g_orcFortBuilt) return;
    g_orcFortBuilt = true;
    T3CMeshBuilder b;
    const float R = kOrcFortRadius, gate = kOrcFortGateYaw;
    const Color log = { 70, 50, 34, 255 }, logDk = { 52, 38, 28, 255 }, red = { 150, 36, 28, 255 }, hide = { 132, 102, 72, 255 };
    auto P = [&](float ang, float r) { return Vector2{ cosf(gate + ang) * r, sinf(gate + ang) * r }; };
    // palisade: two staggered rings of thick logs, red-tipped, with outward stakes
    int n = (int)(6.2832f * R / 10.0f);
    for (int ring = 0; ring < 2; ring++)
        for (int i = 0; i < n; i++) {
            float a = 6.2832f * (i + ring * 0.5f) / n;
            float rel = atan2f(sinf(a), cosf(a));
            if (fabsf(rel) < 0.17f) continue; // the gateway
            float rr = R + ring * 8.0f, h = (ring ? 58.0f : 70.0f) + T3CHash01((float)i, (float)ring) * 14.0f;
            Vector2 q = P(a, rr);
            T3CCylinder(b, q.x, 0.0f, q.y, h, 5.6f, 5.0f, 6, (i + ring) % 3 ? log : logDk, false, false);
            T3CCylinder(b, q.x, h, q.y, h + 11.0f, 5.0f, 0.3f, 6, i % 4 == 0 ? red : Color{ 120, 96, 70, 255 }, false, false);
            if (ring == 1 && i % 2 == 0) { // outward stakes against a charge
                Vector2 o = P(a, rr + 6.0f), t = P(a, rr + 30.0f);
                T3CStake(b, { o.x, 8.0f, o.y }, { t.x, 26.0f, t.y }, 2.6f, log);
            }
        }
    // gatehouse: two square towers, a walkway beam and the horned skull over the gate
    for (int side = -1; side <= 1; side += 2) {
        Vector2 t = P(side * 0.22f, R + 4.0f);
        T3CBox(b, t.x, 55.0f, t.y, 30.0f, 110.0f, 30.0f, logDk);
        for (int k = 0; k < 4; k++) { // crenellations
            float ox = (k % 2 ? 1 : -1) * 11.0f, oz = (k / 2 ? 1 : -1) * 11.0f;
            T3CBox(b, t.x + ox, 116.0f, t.y + oz, 8.0f, 12.0f, 8.0f, log);
        }
        T3CStake(b, { t.x, 110.0f, t.y }, { t.x, 150.0f, t.y }, 1.6f, Color{ 90, 70, 50, 255 }); // banner pole
    }
    {
        Vector2 a = P(-0.22f, R + 4.0f), c = P(0.22f, R + 4.0f), m = P(0.0f, R + 10.0f);
        float bx = (a.x + c.x) * 0.5f, bz = (a.y + c.y) * 0.5f;
        float len = hypotf(c.x - a.x, c.y - a.y);
        float yawG = gate;
        // walkway: a slab spanning the gap between the towers
        for (int k = 0; k <= 8; k++) {
            float t = k / 8.0f;
            T3CBox(b, a.x + (c.x - a.x) * t, 92.0f, a.y + (c.y - a.y) * t, 12.0f, 7.0f, 12.0f, log);
        }
        (void)bx; (void)bz; (void)len;
        T3CSkull(b, m.x, 108.0f, m.y, 2.1f, yawG, true);
    }
    // hide huts round the yard
    const float hutA[5] = { 1.2f, 1.75f, -1.2f, -1.75f, 2.4f };
    for (int i = 0; i < 5; i++) {
        Vector2 h = P(hutA[i], 120.0f);
        T3CCylinder(b, h.x, 0.0f, h.y, 24.0f, 24.0f, 22.0f, 10, hide);
        T3CCylinder(b, h.x, 24.0f, h.y, 56.0f, 28.0f, 2.0f, 10, ColorBrightness(hide, -0.2f), false, false);
        T3CStake(b, { h.x, 50.0f, h.y }, { h.x + 4.0f, 70.0f, h.y }, 1.2f, logDk); // poles poking out the top
        T3CStake(b, { h.x, 50.0f, h.y }, { h.x - 4.0f, 68.0f, h.y + 3.0f }, 1.2f, logDk);
    }
    // the Warlord's longhouse at the back (beyond his spot), gable roof, antler horns
    {
        Vector2 c = P(3.1416f, 160.0f);
        float fx = cosf(gate), fz = sinf(gate); // local x runs along the gate axis
        float sx = -fz, sz = fx;
        auto W = [&](float lx, float ly, float lz) { return Vector3{ c.x + fx * lx + sx * lz, ly, c.y + fz * lx + sz * lz }; };
        const float hl = 34.0f, hw = 62.0f, hh = 42.0f;
        // walls as boxes along each side
        for (int k = -6; k <= 6; k++) T3CBox(b, W(0, 0, k * 10.0f).x, hh * 0.5f, W(0, 0, k * 10.0f).z, 64.0f * 0 + 68.0f, hh, 10.5f, k % 2 ? log : logDk);
        // roof
        float r0[3], r1[3], r2[3], r3[3], a0[3], a1[3];
        Vector3 v;
        v = W(-hl - 8, hh, -hw - 6); r0[0] = v.x; r0[1] = v.y; r0[2] = v.z;
        v = W(-hl - 8, hh, hw + 6);  r1[0] = v.x; r1[1] = v.y; r1[2] = v.z;
        v = W(0, hh + 34, hw + 6);    a1[0] = v.x; a1[1] = v.y; a1[2] = v.z;
        v = W(0, hh + 34, -hw - 6);   a0[0] = v.x; a0[1] = v.y; a0[2] = v.z;
        T3CQuad(b, r0, r1, a1, a0, Color{ 96, 76, 50, 255 });
        v = W(hl + 8, hh, -hw - 6); r2[0] = v.x; r2[1] = v.y; r2[2] = v.z;
        v = W(hl + 8, hh, hw + 6);  r3[0] = v.x; r3[1] = v.y; r3[2] = v.z;
        T3CQuad(b, r3, r2, a0, a1, Color{ 84, 66, 44, 255 });
        T3CPushTri(b, r0, a0, r2, logDk); T3CPushTri(b, r1, r3, a1, logDk); // gable ends
        Vector3 top = W(0, hh + 34, hw + 6), top2 = W(0, hh + 34, -hw - 6);
        T3CStake(b, top, { top.x + sx * 22, top.y + 16, top.z + sz * 22 }, 2.4f, Color{ 200, 186, 150, 255 }); // crossed horns
        T3CStake(b, top2, { top2.x - sx * 22, top2.y + 16, top2.z - sz * 22 }, 2.4f, Color{ 200, 186, 150, 255 });
        Vector3 dr = W(hl + 0.5f, 0, 0);
        T3CBox(b, dr.x, 17.0f, dr.z, 3.0f, 34.0f, 22.0f, Color{ 30, 22, 18, 255 }); // dark doorway
        T3CSkull(b, W(hl + 4, 44, 0).x, 44.0f, W(hl + 4, 44, 0).z, 1.3f, gate, true);
    }
    // bonfire: stone ring and a log pyre
    for (int i = 0; i < 12; i++) {
        float a = 6.2832f * i / 12;
        T3CSphere(b, cosf(a) * 20.0f, 3.0f, sinf(a) * 20.0f, 6.0f, 4.0f, 6.0f, 5, 6, Color{ 96, 92, 88, 255 });
    }
    for (int i = 0; i < 6; i++) {
        float a = i * 1.047f;
        T3CStake(b, { cosf(a) * 14.0f, 0.0f, sinf(a) * 14.0f }, { cosf(a) * 2.0f, 24.0f, sinf(a) * 2.0f }, 2.6f, logDk);
    }
    // war drum on its frame
    {
        Vector2 d = P(3.1416f + 0.7f, 95.0f);
        T3CCylinder(b, d.x, 10.0f, d.y, 34.0f, 16.0f, 16.0f, 12, Color{ 110, 60, 40, 255 });
        T3CCylinder(b, d.x, 34.0f, d.y, 35.0f, 16.5f, 16.5f, 12, Color{ 200, 176, 130, 255 });
        for (int k = 0; k < 4; k++) {
            float a = k * 1.5708f + 0.785f;
            T3CStake(b, { d.x + cosf(a) * 18, 0, d.y + sinf(a) * 18 }, { d.x + cosf(a) * 14, 22, d.y + sinf(a) * 14 }, 2.0f, logDk);
        }
    }
    // skull totems lining the approach and the yard, bone piles
    const float totA[6] = { 0.45f, -0.45f, 0.9f, -0.9f, 2.9f, -2.9f };
    const float totR[6] = { R + 50.0f, R + 50.0f, 70.0f, 70.0f, 105.0f, 105.0f };
    for (int i = 0; i < 6; i++) {
        Vector2 t = P(totA[i], totR[i]);
        T3CStake(b, { t.x, 0, t.y }, { t.x, 58.0f, t.y }, 2.8f, logDk);
        T3CSkull(b, t.x, 56.0f, t.y, 1.1f, gate + totA[i], i < 2);
        T3CBox(b, t.x, 40.0f, t.y, 16.0f, 3.0f, 3.0f, red); // a strip of red cloth
    }
    for (int i = 0; i < 5; i++) {
        Vector2 q = P(0.6f + i * 1.1f, 60.0f + (i % 3) * 25.0f);
        for (int k = 0; k < 5; k++) {
            float a = k * 1.3f + i;
            T3CStake(b, { q.x + cosf(a) * 5, 1.5f, q.y + sinf(a) * 5 }, { q.x + cosf(a + 2) * 9, 3.0f, q.y + sinf(a + 2) * 9 }, 1.4f, Color{ 222, 214, 190, 255 });
        }
        if (i % 2 == 0) T3CSkull(b, q.x, 5.0f, q.y, 0.8f, (float)i, false);
    }
    // trampled earth yard
    for (int i = 0; i < 28; i++) {
        float a0 = 6.2832f * i / 28, a1 = 6.2832f * (i + 1) / 28, r = R - 8.0f;
        float o[3] = { 0, 0.4f, 0 }, p0[3] = { cosf(a0) * r, 0.4f, sinf(a0) * r }, p1[3] = { cosf(a1) * r, 0.4f, sinf(a1) * r };
        T3CPushTri(b, o, p1, p0, Color{ 104, 88, 66, 255 });
    }
    g_orcFortModel = T3CFinish(b);
    Town3DApplyLitShader(g_orcFortModel);
}
static void DrawFireGlow(float x, float y, float z, float r, float k) {
    float t = (float)GetTime();
    float fl = 0.8f + 0.2f * sinf(t * 11.0f + x) * sinf(t * 4.3f + z), rr = r * fl;
    rlSetTexture(GlowTex().id);
    rlBegin(RL_QUADS);
    rlColor4ub((unsigned char)(255 * k), (unsigned char)(150 * k), (unsigned char)(60 * k), 255);
    rlTexCoord2f(0, 0); rlVertex3f(x - rr, y - rr, z); rlTexCoord2f(1, 0); rlVertex3f(x + rr, y - rr, z);
    rlTexCoord2f(1, 1); rlVertex3f(x + rr, y + rr, z); rlTexCoord2f(0, 1); rlVertex3f(x - rr, y + rr, z);
    rlTexCoord2f(0, 0); rlVertex3f(x, y - rr, z - rr); rlTexCoord2f(1, 0); rlVertex3f(x, y - rr, z + rr);
    rlTexCoord2f(1, 1); rlVertex3f(x, y + rr, z + rr); rlTexCoord2f(0, 1); rlVertex3f(x, y + rr, z - rr);
    rlEnd();
    rlSetTexture(0);
}
static void Wild3DDrawOrcFort(bool shadowPass, const Town3DCam* cull) {
    const Vector2 c = kOrcFortPos;
    if (cull && !Wild3DInView(*cull, c.x, c.y, kOrcFortRadius + 80.0f)) return;
    OrcFortBuild();
    float gy = GroundY(c.x, c.y);
    DrawModel(g_orcFortModel, { c.x, gy, c.y }, 1.0f, WHITE);
    Wild3DBuildDressing();
    const Wild3DDressing& D = g_wild3dDress;
    auto prop = [&](int id, float ang, float rad, float y, float faceDeg, float sc, Color tint) {
        if (!D.ok[id]) return;
        float x = c.x + cosf(kOrcFortGateYaw + ang) * rad, z = c.y + sinf(kOrcFortGateYaw + ang) * rad;
        DrawModelEx(D.models[id], { x, GroundY(x, z) + y, z }, { 0, 1, 0 }, faceDeg, { sc, sc, sc }, tint);
    };
    float gd = -kOrcFortGateYaw * RAD2DEG;
    const Color warRed = { 170, 60, 50, 255 };
    for (int side = -1; side <= 1; side += 2) prop(kWPFlagRed, side * 0.22f, kOrcFortRadius + 4.0f, 110.0f, gd, kWPScaleProp * 1.4f, warRed);
    prop(kWPWeaponRack, 0.6f, 80.0f, 0, gd + 50, kWPScaleProp, Color{ 150, 130, 110, 255 });
    prop(kWPWeaponRack, -0.6f, 80.0f, 0, gd - 50, kWPScaleProp, Color{ 150, 130, 110, 255 });
    prop(kWPCrateBig, 2.3f, 150.0f, 0, 30, kWPScaleProp, Color{ 150, 130, 110, 255 });
    prop(kWPBarrel, -2.3f, 150.0f, 0, 0, kWPScaleProp, Color{ 150, 130, 110, 255 });
    prop(kWPSack, -2.1f, 160.0f, 0, 20, kWPScaleProp, WHITE);
    prop(kWPLumber, 1.9f, 165.0f, 0, gd, kWPScaleProp, WHITE);
    if (shadowPass) return;
    float night = g_t3dNight, t = (float)GetTime();
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    DrawFireGlow(c.x, gy + 20.0f, c.y, 26.0f, 1.0f);
    DrawFireGlow(c.x, gy + 10.0f, c.y, 40.0f, 0.55f);
    GlowPool(c.x, c.y, gy + 0.8f, 90.0f + 60.0f * night, Color{ (unsigned char)(140 + 90 * night), (unsigned char)(70 + 40 * night), 30, 255 });
    for (int side = -1; side <= 1; side += 2) { // tower braziers
        float a = kOrcFortGateYaw + side * 0.22f;
        DrawFireGlow(c.x + cosf(a) * (kOrcFortRadius + 4), gy + 124.0f, c.y + sinf(a) * (kOrcFortRadius + 4), 12.0f, 0.5f + 0.5f * night);
    }
    rlEnableDepthMask();
    EndBlendMode();
    BeginBlendMode(BLEND_ALPHA); // thick bonfire smoke
    rlSetTexture(GlowTex().id);
    rlBegin(RL_QUADS);
    for (int i = 0; i < 9; i++) {
        float ph = fmodf(t * 0.18f + i / 9.0f, 1.0f);
        Vector3 p = { c.x + ph * 40.0f + sinf(t + i) * 5.0f, gy + 30.0f + ph * 150.0f, c.y + ph * 16.0f };
        float r = 10.0f + ph * 30.0f;
        unsigned char al = (unsigned char)(120 * (1.0f - ph) * std::min(1.0f, ph * 8.0f));
        unsigned char v = (unsigned char)(110 - 50 * night);
        rlColor4ub(v, v, v, al);
        rlTexCoord2f(0, 0); rlVertex3f(p.x - r, p.y - r, p.z); rlTexCoord2f(1, 0); rlVertex3f(p.x + r, p.y - r, p.z);
        rlTexCoord2f(1, 1); rlVertex3f(p.x + r, p.y + r, p.z); rlTexCoord2f(0, 1); rlVertex3f(p.x - r, p.y + r, p.z);
    }
    rlEnd();
    rlSetTexture(0);
    EndBlendMode();
}
static void Wild3DDrawHouse(GameState& s, bool shadowPass); // Housing 2.0 (below, with the room surfaces)
static Vector3 g_houseSignPos = { 0, -1, 0 };                // the homestead's sign post (y < 0: none built)
static void Wild3DDrawSceneContents(GameState& s, bool shadowPass, const Town3DCam* cull) {
    Wild3DLoadModels();
    Wild3DEnsureGround();
    Wild3DBuildScatter();
    auto vis = [&](float x, float z, float r) { return !cull || Wild3DInView(*cull, x, z, r); };

    // Ground: procedural meadow with baked paths, plus a large flat outer field
    // so the horizon never shows a hard edge.
    DrawModel(g_wild3dGround.model, { 0, 0, 0 }, 1.0f, WHITE); // hilly mesh is in world coordinates
    DrawPlane({ 1600, -15.0f, 1600 }, { 8000, 8000 }, Color{ 92, 132, 70, 255 });
    DrawPlane({ 5600, -2.0f, 1600 }, { 4800, 8000 }, Color{ 44, 96, 122, 255 }); // open sea past the coast (2026-09-26)

    // Region dressing: tree clusters, rocks, camps, horizon ring (main pass only).
    if (!shadowPass) Wild3DDrawDressing(cull);
    // Extra scatter (3D-only filler; see Wild3DBuildScatter).
    for (const Wild3DScatterItem& it : g_wild3dScatter) {
        if (!vis(it.x, it.z, 80.0f)) continue;
        Wild3DDrawScatterOne(it, shadowPass);
    }
    // Swaying grass tufts along the paths (main pass only - never shadows).
    if (!shadowPass) T3DGrassDrawWild(cull);
    // Decorative foliage from the 2D data.
    for (const WildernessFoliage& f : kWildernessFoliage) {
        if (!vis(f.pos.x, f.pos.y, 60.0f)) continue;
        Wild3DDrawFoliageOne(f, shadowPass);
    }
    // Gather nodes at their exact 2D positions.
    for (size_t i = 0; i < kWildernessGatherNodes.size(); i++) {
        const WildernessGatherNode& n = kWildernessGatherNodes[i];
        if (!vis(n.pos.x, n.pos.y, 80.0f)) continue;
        Wild3DDrawGatherNode(n, (int)i, s.worldTime);
    }
    // Phase 2 - Saltmere Docks: wilderness landmark on the Salt Coast (decorative).
    for (const CoastProp& d : kSaltDocks) {
        if (!vis(d.pos.x, d.pos.y, 120.0f)) continue;
        DrawCoastProp3D(d.kind, d.pos.x, d.pos.y, d.size, s.worldTime);
    }
    // Dungeon entrances.
    for (const WildernessDungeonEntrance& e : kWildernessDungeonEntrances) {
        if (!vis(e.pos.x, e.pos.y, 90.0f)) continue;
        Wild3DDrawEntrance(e);
    }
    // Phase 6 - connective tissue landmarks, 3D.
    for (size_t si = 0; si < kShrines.size(); si++) { // virtue shrines: stone dais + light beam
        const ShrineDef& shrine = kShrines[si];
        if (!vis(shrine.pos.x, shrine.pos.y, 90.0f)) continue;
        DrawCylinder({ shrine.pos.x, 3, shrine.pos.y }, 14, 16, 6, 10, Color{ 200, 195, 175, 255 });
        DrawCylinder({ shrine.pos.x, 10, shrine.pos.y }, 5, 7, 14, 8, Color{ 225, 220, 195, 255 });
        DrawCylinder({ shrine.pos.x, 60, shrine.pos.y }, 3, 3, 100, 8, Color{ 255, 245, 200, 90 });
    }
    { // the Fields of Sorrow: gray ground wash + broken pillars
        if (vis(kFieldsOfSorrow.x, kFieldsOfSorrow.y, kFieldsOfSorrowRadius + 60.0f)) {
            DrawCylinder({ kFieldsOfSorrow.x, 1, kFieldsOfSorrow.y }, kFieldsOfSorrowRadius, kFieldsOfSorrowRadius, 2, 24,
                           Color{ 110, 110, 120, 90 });
            static const std::array<Vector2, 5> kSorrowPillars = {{
                {1830, 2240}, {1970, 2260}, {1900, 2360}, {1850, 2320}, {1950, 2340}
            }};
            for (auto& pp : kSorrowPillars) {
                float h = 20.0f + Town3DHash01(pp.x, pp.y) * 30.0f;
                DrawCube({ pp.x, h / 2, pp.y }, 8, h, 8, Color{ 130, 128, 135, 255 });
                DrawCube({ pp.x + 6, 2, pp.y + 4 }, 10, 4, 10, Color{ 115, 113, 120, 255 });
            }
        }
    }
    Wild3DDrawRivalCamp(s, shadowPass, cull); // Murder Inc.'s war camp (2026-09-27)
    Wild3DDrawOrcFort(shadowPass, cull);      // Grimtusk Hold, the orc fortress (2026-09-27)
    if (s.notoriety > 1.0f || s.refugeKnown) { // the outlaw refuge: dark tent + red lantern
        if (vis(kOutlawRefuge.x, kOutlawRefuge.y, 90.0f)) {
            T3DLiftScope lift_(kOutlawRefuge.x, kOutlawRefuge.y);
            DrawCylinder({ kOutlawRefuge.x, 12, kOutlawRefuge.y }, 2, 16, 24, 4, Color{ 45, 40, 55, 255 });
            DrawSphere({ kOutlawRefuge.x + 18, 16, kOutlawRefuge.y }, 4.0f, Color{ 255, 60, 50, 220 });
        }
    }
    // Travel gates.
    if (vis(kWildernessReturnGatePos.x, kWildernessReturnGatePos.y, 90.0f))
        Wild3DDrawGate(kWildernessReturnGatePos.x, kWildernessReturnGatePos.y,
                       Color{ 140, 110, 80, 255 }, Color{ 110, 85, 60, 255 });
    if (vis(kWildernessTown2GatePos.x, kWildernessTown2GatePos.y, 90.0f))
        Wild3DDrawGate(kWildernessTown2GatePos.x, kWildernessTown2GatePos.y,
                       Color{ 150, 148, 142, 255 }, Color{ 118, 116, 110, 255 });
    // Phase 3 - Frostmere gate: icy pale-blue gate.
    if (vis(kWildernessTown3GatePos.x, kWildernessTown3GatePos.y, 90.0f))
        Wild3DDrawGate(kWildernessTown3GatePos.x, kWildernessTown3GatePos.y,
                       Color{ 190, 210, 228, 255 }, Color{ 150, 175, 200, 255 });
    // Phase 4 - Cragmoor gate: granite gray gate.
    if (vis(kWildernessTown4GatePos.x, kWildernessTown4GatePos.y, 90.0f))
        Wild3DDrawGate(kWildernessTown4GatePos.x, kWildernessTown4GatePos.y,
                       Color{ 150, 142, 128, 255 }, Color{ 115, 108, 96, 255 });

    // Custom housing (2026-09-25) - for-sale signs on unowned plots; floor slab +
    // wall/door boxes on owned ones. DrawCube rides the active sun/shadow shader
    // like the gate/prop boxes above. Owned plots draw the Housing 2.0 shell.
    for (size_t pi = 0; pi < kHousePlots.size(); pi++) {
        const HousePlot& hp = kHousePlots[pi];
        float pr = hp.cells * kHouseCellSize * 0.6f;
        if (!vis(hp.pos.x, hp.pos.y, pr)) continue;
        bool owned = (int)pi == s.housePlotIdx;
        if (!owned) {
            if (!shadowPass) {
                DrawCube({ hp.pos.x, 25, hp.pos.y }, 8, 50, 8, Color{ 110, 80, 50, 255 });
                DrawCube({ hp.pos.x, 62, hp.pos.y }, 76, 26, 6, Color{ 150, 115, 70, 255 });
            }
            continue;
        }
        Wild3DDrawHouse(s, shadowPass); // textured shell + roof (Housing 2.0)
    }

    bool wasEngaged = s.wildEngaged.has_value();
    // Phase 3 procedural creatures (kit shader matches the sun/shadow pipeline).
    T3CKitUseSunShader();
    auto kitDist = [&](float x, float z) {
        return (cull && !shadowPass) ? hypotf(cull->pos.x - x, cull->pos.z - z) : 0.0f;
    };
    // Tameable creatures at their exact 2D spawn spots.
    for (size_t i = 0; i < kWildernessCreatureSpots.size(); i++) {
        const WildernessCreatureSpot& sp = kWildernessCreatureSpots[i];
        if (!vis(sp.pos.x, sp.pos.y, 70.0f)) continue;
        T3CQuadLook look = T3CCreatureLook(sp.creatureIdx);
        T3CAnim ca = T3CMakeAnim(kT3CTrackCreatureWild + (int)i, sp.pos.x, sp.pos.y, !shadowPass);
        {   // Animated model where one fits the species (2026-09-26).
            AnimalPose ap; ap.move = ca.move; ap.time = ca.t + ca.seed * 0.37f; ap.track = kT3CTrackCreatureWild + (int)i;
            if (sp.creatureIdx == 1) ap.recolor = Color{ 128, 112, 96, 150 }; // Timber Wolf: grey-brown
            if (DrawAnimal(AnimalForCreature(sp.creatureIdx), sp.pos.x, sp.pos.y,
                           Town3DHash01(sp.pos.x, sp.pos.y) * 6.2832f, 1.0f, WHITE, ap, shadowPass)) continue;
        }
        T3CDrawQuad(g_t3cQuads[look.specIdx].parts, sp.pos.x, sp.pos.y,
                    Town3DHash01(sp.pos.x, sp.pos.y) * 6.2832f,
                    look.scale, look.coat, ca, kitDist(sp.pos.x, sp.pos.y), shadowPass);
    }
    WildAnimalsUpdateDraw(s, cull, shadowPass); // ambient deer, stags, foxes (2026-09-26)
    // Monsters at their live positions (the engaged one at its fight position,
    // pack attackers at their chase positions).
    bool wildDying = false;
    for (const auto& d : s.dyingMonsters) if (d.zone == 0) { wildDying = true; break; }
    for (size_t i = 0; i < kWildernessMonsterSpots.size(); i++) {
        bool eng = wasEngaged && s.wildEngaged->spotIdx == (int)i;
        // Empty slots (waiting to respawn) draw nothing - except a slot mid-death-
        // animation, which draws the shrinking body instead.
        const GameState::DyingMonster* dying = wildDying ? FindDyingWildSpot(s, (int)i) : nullptr;
        bool isDying = dying != nullptr;
        const GameState::ActiveMonster* extra = (!eng && !isDying) ? FindWildExtra(s, (int)i) : nullptr;
        if (!eng && !isDying && !extra && s.wildSpotRespawn[i] > 0.0f) continue;
        Vector2 mp = eng ? s.wildEngaged->pos : (isDying ? dying->pos : (extra ? extra->pos : WildernessMonsterLivePos((int)i, s.worldTime)));
        if (!vis(mp.x, mp.y, 70.0f)) continue;
        float face = (eng || extra) ? atan2f(s.wildernessPlayerPos.y - mp.y, s.wildernessPlayerPos.x - mp.x)
                         : Wild3DWanderFacing((int)i, mp.x, mp.y, s.worldTime);
        T3CMonLook mlook = T3CMonsterLook(kWildernessMonsterSpots[i].iconIdx);
        T3CAnim ma = T3CMakeAnim(kT3CTrackMonsterWild + (int)i, mp.x, mp.y, !shadowPass);
        float shrink = isDying ? std::max(0.05f, dying->timer / dying->duration) : 1.0f;
        // Combat read (2026-09-24): the engaged monster's lunge pose rides
        // monsterAttackT; it flashes white-hot then red while monsterHurtT is live.
        // Pack attackers (2026-09-25) flash the same way when hit, no lunge pose.
        float mAtk = (eng && !isDying) ? MonsterCombatPhase3D(s.wildEngaged->monsterAttackT) : -1.0f;
        float mHurtT = -1.0f;
        if (!isDying) {
            if (eng) mHurtT = s.wildEngaged->monsterHurtT;
            else if (extra) mHurtT = extra->monsterHurtT;
        }
        { // a guild member is farming it: it turns and trades blows with them
            Vector2 fp; float fsw;
            if (!eng && !extra && !isDying && GuildFarmingSpot(s, (int)i, &fp, &fsw)) {
                face = atan2f(fp.y - mp.y, fp.x - mp.x);
                mAtk = MonsterCombatPhase3D(fmodf(fsw + kGuildSwingPeriod * 0.5f, kGuildSwingPeriod));
                if (fsw > 0.12f && fsw < 0.3f) mHurtT = 0.0f; // its swing lands
            }
        }
        Color anRecolor = { 0, 0, 0, 0 }; float anScale = 1.0f;
        int anId = mlook.humanoid ? -1 : AnimalForMonster(kWildernessMonsterSpots[i].iconIdx, &anRecolor, &anScale);
        if (anId >= 0) { // animated model (2026-09-26): its own attack/hit/death clips
            AnimalPose ap;
            ap.recolor = anRecolor;
            Color named = AnimalRecolorForMonsterName(kWildernessMonsterSpots[i].name);
            if (named.a > 0) ap.recolor = named;
            ap.move = ma.move; ap.time = ma.t + ma.seed * 0.37f; ap.track = kT3CTrackMonsterWild + (int)i;
            ap.attackT = mAtk; ap.hurtT = mHurtT;
            if (isDying) ap.deathT = 1.0f - dying->timer / std::max(0.01f, dying->duration);
            if (DrawAnimal(anId, mp.x, mp.y, face, anScale, CombatHitTint(mHurtT, WHITE, Color{ 220, 90, 90, 255 }), ap, shadowPass))
                continue;
        }
        if (mlook.humanoid) {
            HumanOutfit ho = HumanOutfitForWildMonster(kWildernessMonsterSpots[i].iconIdx, kWildernessMonsterSpots[i].name, mlook);
            float dT = isDying ? 1.0f - dying->timer / std::max(0.01f, dying->duration) : -1.0f;
            if (DrawHuman(kT3CTrackMonsterWild + (int)i, mp.x, mp.y, face, mlook.scale * 0.94f,
                          CombatHitTint(mHurtT, WHITE, Color{ 220, 90, 90, 255 }),
                          ho, HumanMonsterPose(ma.move, mAtk, mHurtT, dT, eng), shadowPass))
                continue;
            T3CDrawHumanoid(g_t3cHumans[0].parts, mp.x, mp.y, face, mlook.scale * shrink,
                            CombatHitTint(mHurtT, mlook.shirt, Color{ 220, 90, 90, 255 }), mlook.pants, mlook.skin, ma, shadowPass,
                            mAtk, -1.0f);
        } else {
            T3CDrawQuad(g_t3cQuads[mlook.specIdx].parts, mp.x, mp.y, face,
                        mlook.scale * shrink, CombatHitTint(mHurtT, mlook.coat, Color{ 220, 90, 90, 255 }), ma, kitDist(mp.x, mp.y), shadowPass,
                        mAtk);
        }
    }
    // The Rival Adventurer - while their death animation plays, the fading body at
    // the kill site is drawn instead of the patrolling rival (no double-draw);
    // they "retreat" (RivalFightEnded already put them back on patrol) rather
    // than leaving a corpse.
    const GameState::DyingMonster* rivalDying3D = FindDyingRival(s);
    {
        Vector2 rp = rivalDying3D ? rivalDying3D->pos
                     : ((wasEngaged && s.wildEngaged->isRival) ? s.wildEngaged->pos : s.rivalPos);
        if (vis(rp.x, rp.y, 70.0f)) {
            // Faces you when it's after you (or fighting you); otherwise it faces
            // its work or the way it's walking (living guild, 2026-09-26).
            bool rAfterYou = (wasEngaged && s.wildEngaged->isRival) || s.rivalActivity != GameState::RivalActivity::Patrol;
            float ryaw = rAfterYou ? atan2f(s.wildernessPlayerPos.y - rp.y, s.wildernessPlayerPos.x - rp.x) : s.rivalMind.yaw;
            T3CAnim ra = T3CMakeAnim(kT3CTrackRival, rp.x, rp.y, !shadowPass);
            float rscale = rivalDying3D ? std::max(0.05f, rivalDying3D->timer / rivalDying3D->duration) : 1.0f;
            // Combat read (2026-09-24): engaged Rival lunges/flashes with its timers.
            bool rEng = wasEngaged && s.wildEngaged->isRival && !rivalDying3D;
            float rAtk = rEng ? MonsterCombatPhase3D(s.wildEngaged->monsterAttackT) : -1.0f;
            float rDeath = rivalDying3D ? 1.0f - rivalDying3D->timer / std::max(0.01f, rivalDying3D->duration) : -1.0f;
            float rHurt = rEng ? s.wildEngaged->monsterHurtT : -1.0f;
            HumanPose rPose = HumanMonsterPose(ra.move, rAtk, rHurt, rDeath, rEng);
            if (!rEng && !rivalDying3D) GuildWorkPose(s.rivalMind, s.rivalActivity, rPose);
            if (!DrawHuman(kT3CTrackRival, rp.x, rp.y, ryaw, 1.02f, CombatHitTint(rHurt, WHITE, Color{ 220, 90, 90, 255 }),
                           HumanOutfitRival(), rPose, shadowPass))
            T3CDrawHumanoid(g_t3cHumans[3].parts, rp.x, rp.y, ryaw, rscale,
                            CombatHitTint(rEng ? s.wildEngaged->monsterHurtT : -1.0f, Color{ 150, 60, 55, 255 }, Color{ 220, 90, 90, 255 }),
                            Color{ 60, 50, 55, 255 },
                            Color{ 235, 200, 170, 255 }, ra, shadowPass, rAtk, -1.0f);
        }
    }
    // Murder Inc. blades - the same humanoid kit as the champion, but in dark
    // dried-blood guild colors and slightly smaller, so the crew reads as the
    // crew and the champion stays the champion.
    for (int bi = 0; bi < kBladeCount; bi++) {
        // While a blade's death animation plays, the fading body at the kill site
        // is drawn instead of the patrolling blade (no double-draw) - same
        // retreat-not-death treatment as the champion above.
        const GameState::DyingMonster* bladeDying3D = FindDyingBlade(s, bi);
        Vector2 bp = bladeDying3D ? bladeDying3D->pos
                     : ((wasEngaged && s.wildEngaged->bladeIdx == bi) ? s.wildEngaged->pos : s.blades[bi].pos);
        if (vis(bp.x, bp.y, 70.0f)) {
            bool bAfterYou = (wasEngaged && s.wildEngaged->bladeIdx == bi) || s.blades[bi].activity != GameState::RivalActivity::Patrol;
            float byaw = bAfterYou ? atan2f(s.wildernessPlayerPos.y - bp.y, s.wildernessPlayerPos.x - bp.x) : s.blades[bi].mind.yaw;
            T3CAnim ba = T3CMakeAnim(kT3CTrackBladeWild + bi, bp.x, bp.y, !shadowPass);
            float bscale = (bladeDying3D ? std::max(0.05f, bladeDying3D->timer / bladeDying3D->duration) : 1.0f) * 0.95f;
            // Combat read (2026-09-24): engaged blade lunges/flashes with its timers.
            bool bEng = wasEngaged && s.wildEngaged->bladeIdx == bi && !bladeDying3D;
            float bAtk = bEng ? MonsterCombatPhase3D(s.wildEngaged->monsterAttackT) : -1.0f;
            float bDeath = bladeDying3D ? 1.0f - bladeDying3D->timer / std::max(0.01f, bladeDying3D->duration) : -1.0f;
            float bHurt = bEng ? s.wildEngaged->monsterHurtT : -1.0f;
            HumanPose bPose = HumanMonsterPose(ba.move, bAtk, bHurt, bDeath, bEng);
            if (!bEng && !bladeDying3D) GuildWorkPose(s.blades[bi].mind, s.blades[bi].activity, bPose);
            if (!DrawHuman(kT3CTrackBladeWild + bi, bp.x, bp.y, byaw, 0.95f, CombatHitTint(bHurt, WHITE, Color{ 220, 90, 90, 255 }),
                           HumanOutfitBlade(), bPose, shadowPass))
            T3CDrawHumanoid(g_t3cHumans[3].parts, bp.x, bp.y, byaw, bscale,
                            CombatHitTint(bEng ? s.wildEngaged->monsterHurtT : -1.0f, Color{ 70, 25, 30, 255 }, Color{ 220, 90, 90, 255 }),
                            Color{ 35, 30, 35, 255 },
                            Color{ 220, 190, 165, 255 }, ba, shadowPass, bAtk, -1.0f);
        }
    }
    // Roaming innocents (only the ones currently present) - fixed per-identity
    // tints from kInnocentDefs so Tam/Liora/Silas/Garran read as distinct people.
    for (size_t i = 0; i < kWildernessInnocentSpots.size(); i++) {
        if (!s.innocentSpots[i].present) continue;
        Vector2 ip = WildernessInnocentLivePos((int)i, s.worldTime);
        if (!vis(ip.x, ip.y, 70.0f)) continue;
        Vector2 ia = WildernessInnocentLivePos((int)i, s.worldTime + 0.6f);
        float idx2 = ia.x - ip.x, idz = ia.y - ip.y;
        float iyaw = (idx2 * idx2 + idz * idz < 0.04f)
                     ? Town3DHash01(ip.x, ip.y) * 6.2832f : atan2f(idz, idx2);
        T3CAnim ia2 = T3CMakeAnim(kT3CTrackInnocentWild + (int)i, ip.x, ip.y, !shadowPass);
        const InnocentDef& idef = kInnocentDefs[std::clamp(s.innocentSpots[i].identity, 0, 3)];
        {
            HumanOutfit io = HumanOutfitPlain(idef.skin, idef.shirt, idef.pants, Color{ 70, 50, 34, 255 }, Color{ 90, 64, 42, 255 });
            io.cloak = true; io.cloakCol = ColorBrightness(idef.pants, -0.1f);
            HumanPose ihp; ihp.move = ia2.move;
            if (DrawHuman(kT3CTrackInnocentWild + (int)i, ip.x, ip.y, iyaw, 0.97f, WHITE, io, ihp, shadowPass)) continue;
        }
        T3CDrawHumanoid(g_t3cHumans[0].parts, ip.x, ip.y, iyaw, 0.95f,
                        idef.shirt, idef.pants, idef.skin, ia2, shadowPass);
    }
    // An innocent you're escorting walks beside you in the 3D world too.
    if (s.escortInnocent >= 0) {
        Vector2 ep = s.escortPos;
        if (vis(ep.x, ep.y, 70.0f)) {
            float eyaw = atan2f(s.wildernessPlayerPos.y - ep.y, s.wildernessPlayerPos.x - ep.x);
            T3CAnim ea = T3CMakeAnim(kT3CTrackInnocentWild + 10, ep.x, ep.y, !shadowPass);
            const InnocentDef& edef = kInnocentDefs[std::clamp(s.escortInnocent, 0, 3)];
            HumanOutfit eo = HumanOutfitPlain(edef.skin, edef.shirt, edef.pants, Color{ 70, 50, 34, 255 }, Color{ 90, 64, 42, 255 });
            eo.cloak = true; eo.cloakCol = ColorBrightness(edef.pants, -0.1f);
            HumanPose ehp; ehp.move = ea.move;
            if (!DrawHuman(kT3CTrackInnocentWild + 10, ep.x, ep.y, eyaw, 0.97f, WHITE, eo, ehp, shadowPass))
            T3CDrawHumanoid(g_t3cHumans[0].parts, ep.x, ep.y, eyaw, 0.95f,
                            edef.shirt, edef.pants, edef.skin, ea, shadowPass);
        }
    }
    // Fallen monsters lie where they died (2026-09-26, UO corpses): the real
    // body in its final death pose, sinking into the ground in its last seconds,
    // with a gold glint while there's still loot on it.
    for (const GameState::WorldCorpse& c : s.worldCorpses) {
        if (c.zone != 0) continue;
        if (!vis(c.pos.x, c.pos.y, 70.0f)) continue;
        Wild3DDrawCorpse(c, shadowPass);
    }
    // AI companion.
    if (Pet* ap = ActivePet(s)) {
        if (vis(s.companionPos.x, s.companionPos.y, 70.0f)) {
            Vector2 d = { s.wildernessPlayerPos.x - s.companionPos.x,
                          s.wildernessPlayerPos.y - s.companionPos.y };
            float face = (d.x * d.x + d.y * d.y > 1.0f) ? atan2f(d.y, d.x) : 0.0f;
            T3CQuadLook plook = T3CPetLook(ap->role);
            T3CAnim pa2 = T3CMakeAnim(kT3CTrackCompanion, s.companionPos.x, s.companionPos.y, !shadowPass);
            T3CDrawQuad(g_t3cQuads[plook.specIdx].parts, s.companionPos.x, s.companionPos.y,
                        face, plook.scale, plook.coat, pa2,
                        kitDist(s.companionPos.x, s.companionPos.y), shadowPass);
        }
    }
    // Player, same humanoid kit as the town 3D view - shrinks during the death
    // animation, ghostly-translucent while a ghost.
    {
        float pyaw = atan2f(s.playerFacing.y, s.playerFacing.x);
        T3CAnim pa3 = T3CMakeAnim(kT3CTrackPlayerWild, s.wildernessPlayerPos.x, s.wildernessPlayerPos.y, !shadowPass);
        Vector2 foe = s.wildEngaged.has_value() ? s.wildEngaged->pos : Vector2{ 0, 0 };
        if (DrawPlayerHuman(s, kT3CTrackPlayerWild, s.wildernessPlayerPos.x, s.wildernessPlayerPos.y, pyaw, pa3.move,
                            s.wildEngaged.has_value() ? &foe : nullptr, shadowPass)) {
            // animated body drawn
        } else if (s.playerDeathAnimT > 0.0f) {
            float pshrink = std::max(0.05f, s.playerDeathAnimT / kPlayerDeathAnimTime);
            T3CDrawHumanoid(g_t3cHumans[2].parts, s.wildernessPlayerPos.x, s.wildernessPlayerPos.y,
                            pyaw, pshrink, Color{ 70, 130, 220, 255 }, Color{ 50, 55, 70, 255 },
                            Color{ 240, 210, 180, 255 }, pa3, shadowPass);
        } else if (s.playerIsGhost) {
            Color g = Fade(Color{ 170, 205, 255, 255 }, 0.45f);
            T3CDrawHumanoid(g_t3cHumans[2].parts, s.wildernessPlayerPos.x, s.wildernessPlayerPos.y,
                            pyaw, 1.0f, g, g, Fade(Color{ 220, 235, 255, 255 }, 0.45f), pa3, shadowPass);
        } else {
            // Combat read (2026-09-24): swing/cast poses ride the engaged
            // monster's timers; the player flashes red and reels on playerHurtT.
            float pAtk = -1.0f, pCast = -1.0f;
            PlayerCombatPhases3D(s, &pAtk, &pCast);
            Color shirt = Color{ 70, 130, 220, 255 };
            float px = s.wildernessPlayerPos.x, pz = s.wildernessPlayerPos.y;
            if (s.playerHurtT >= 0.0f) {
                shirt = Color{ 220, 90, 90, 255 };
                if (s.wildEngaged.has_value()) {
                    Vector2 away = { s.wildernessPlayerPos.x - s.wildEngaged->pos.x,
                                     s.wildernessPlayerPos.y - s.wildEngaged->pos.y };
                    float al = std::sqrt(away.x * away.x + away.y * away.y);
                    if (al > 0.001f) {
                        float kb = 16.0f * (1.0f - s.playerHurtT / 0.30f);
                        px += away.x / al * kb; pz += away.y / al * kb;
                    }
                }
            }
            T3CDrawHumanoid(g_t3cHumans[2].parts, px, pz,
                            pyaw, 1.0f, shirt, Color{ 50, 55, 70, 255 },
                            Color{ 240, 210, 180, 255 }, pa3, shadowPass, pAtk, pCast);
        }
    }
}

// Sun shadow pass for the wilderness: same rlgl depth-FBO tech as the town,
// with the orthographic sun camera widened to cover the 3200-unit world.
// Called from the main loop before the frame's render target is bound.
// Phase 1 deferred item (2026-09-24): frustum-cull the shadow pass. The shadow
// camera covers the whole world, so without culling every scatter/foliage/node
// in the wilderness (~660 draws worst case) renders into the shadowmap every
// frame. The main camera's frustum is a safe cull here: anything outside it is
// invisible anyway, and the sun is steep enough that off-screen casters' shadows
// barely reach into view.
static void Wild3DShadowPass(GameState& s, const Town3DCam* cull) {
    Town3DEnsureShadow();
    if (!g_t3dShadow.ready) return;
    Vector3 center = { 1600, 0, 1600 };
    g_t3dLightCam.position = T3VSub(center, T3VScale(kT3DSunDir, -2600.0f));
    g_t3dLightCam.target = center;
    g_t3dLightCam.up = { 0, 1, 0 };
    g_t3dLightCam.fovy = 4600.0f; // ortho box height; covers the world + margin
    g_t3dLightCam.projection = CAMERA_ORTHOGRAPHIC;
    BeginTextureMode(g_t3dShadow.map);
    ClearBackground(WHITE);
    BeginMode3D(g_t3dLightCam);
    g_t3dLightVP = T3DMatMul(rlGetMatrixModelview(), rlGetMatrixProjection());
    Wild3DDrawSceneContents(s, true, cull);
    EndMode3D();
    EndTextureMode();
}

// Gradient sky dome for the wilderness - same banded-cylinder tech as the
// town, widened so the horizon sits past the fog range.
static void Wild3DDrawSky(Vector3 camPos) {
    const float R = 4200.0f, bandH = 120.0f;
    const int bands = 16;
    T3DSkyBegin(); // pure background, see Town3DDrawSky
    for (int i = 0; i < bands; i++) {
        float t = (float)i / (float)(bands - 1);
        Color col = ColorLerp(g_t3dSkyHorizon, g_t3dSkyZenith, t * t * 0.92f);
        float y0 = -60.0f + i * bandH, y1 = y0 + bandH;
        Town3DSkyBand({ camPos.x, y0, camPos.z }, { camPos.x, y1, camPos.z }, R, 24, col);
    }
    DrawCylinder({ camPos.x, 1861.0f, camPos.z }, R, R, 2.0f, 24, g_t3dSkyZenith);
    T3DDrawStars(camPos, R);
    T3DSkyEnd();
}

// Circling birds over the wilderness - the town's batched rlgl bird tech
// (one draw call), main pass only.
static void Wild3DDrawAmbience(const Town3DCam& c) {
    (void)c;
    float t = (float)GetTime();
    rlDisableBackfaceCulling();
    rlBegin(RL_TRIANGLES);
    for (int i = 0; i < 5; i++) {
        float ang = t * 0.18f + (float)i * 1.2566f;
        float rad = 900.0f + (float)i * 160.0f;
        Vector3 ctr = { 1600.0f + cosf(ang) * rad,
                        560.0f + (float)i * 28.0f + sinf(t * 0.6f + (float)i) * 24.0f,
                        1600.0f + sinf(ang) * rad };
        Vector3 fwd = { -sinf(ang), 0.0f, cosf(ang) };
        Vector3 side = { cosf(ang), 0.0f, -sinf(ang) };
        Vector3 nose = T3VAdd(ctr, T3VScale(fwd, 16.0f));
        Vector3 tail = T3VSub(ctr, T3VScale(fwd, 12.0f));
        float tipY = 6.0f + sinf(t * 8.0f + (float)i * 2.1f) * 18.0f;
        Vector3 lw = { ctr.x + side.x * 26.0f, ctr.y + tipY, ctr.z + side.z * 26.0f };
        Vector3 rw = { ctr.x - side.x * 26.0f, ctr.y + tipY, ctr.z - side.z * 26.0f };
        rlColor4ub(42, 38, 46, 255);
        rlVertex3f(nose.x, nose.y, nose.z); rlVertex3f(tail.x, tail.y, tail.z); rlVertex3f(lw.x, lw.y, lw.z);
        rlVertex3f(nose.x, nose.y, nose.z); rlVertex3f(rw.x, rw.y, rw.z); rlVertex3f(tail.x, tail.y, tail.z);
    }
    rlEnd();
    rlEnableBackfaceCulling();
}

// Nearest interactable for the 3D view's highlight ring + label. Mirrors the
// nearest-search in DrawWildernessScreen (positions only); the real interaction
// logic stays there.
struct Wild3DNearest {
    bool valid = false;
    Vector2 pos{};
    float dist = 1e9f;
    std::string label;
    bool engaged = false;
};
static Wild3DNearest Wild3DNearestInfo(const GameState& s) {
    Wild3DNearest r;
    auto consider = [&](Vector2 pos, const std::string& label) {
        float d = Dist(s.wildernessPlayerPos, pos);
        if (d < r.dist) { r.dist = d; r.valid = true; r.pos = pos; r.label = label; }
    };
    for (const WildernessGatherNode& n : kWildernessGatherNodes)
        consider(n.pos, (n.resource == "fish" ? "Catch fish" : (n.resource == "ice" ? "Chip ice crystals"
            : (n.resource == "richore" ? "Mine rich ore" : "Gather " + n.resource))));
    for (const WildernessCreatureSpot& sp : kWildernessCreatureSpots)
        consider(sp.pos, "Tame " + kWildCreatures[sp.creatureIdx].name);
    bool wasEngaged = s.wildEngaged.has_value();
    for (size_t i = 0; i < kWildernessMonsterSpots.size(); i++) {
        if (s.wildSpotRespawn[i] > 0.0f) continue; // empty - waiting to respawn
        Vector2 mp = (wasEngaged && (int)i == s.wildEngaged->spotIdx) ? s.wildEngaged->pos
                     : WildernessMonsterLivePos((int)i, s.worldTime);
        consider(mp, "Fight " + kWildernessMonsterSpots[i].name);
    }
    consider((wasEngaged && s.wildEngaged->isRival) ? s.wildEngaged->pos : s.rivalPos, "Fight Rival Adventurer");
    for (int bi = 0; bi < kBladeCount; bi++) {
        Vector2 bp = (wasEngaged && s.wildEngaged->bladeIdx == bi) ? s.wildEngaged->pos : s.blades[bi].pos;
        consider(bp, "Fight " + BladeName(bi));
    }
    for (size_t i = 0; i < kWildernessInnocentSpots.size(); i++) {
        if (!s.innocentSpots[i].present) continue;
        consider(WildernessInnocentLivePos((int)i, s.worldTime), "Approach " + InnocentName(s.innocentSpots[i].identity));
    }
    for (const WildernessDungeonEntrance& e : kWildernessDungeonEntrances)
        consider(e.pos, "Enter " + kDungeons[e.dungeonIdx].name);
    for (size_t pi = 0; pi < kHousePlots.size(); pi++)
        consider(HousePlotInteractPos(s.housePlotIdx, s.houseLayout, (int)pi),
                 HousePlotPrompt(s.housePlotIdx, s.houseLayout, (int)pi));
    consider(kWildernessReturnGatePos, "Return to Emberhold");
    consider(kWildernessTown2GatePos, std::string("Enter ") + kTown2Name);
    consider(kWildernessTown3GatePos, std::string("Enter ") + kTown3Name); // Phase 4: was missing since Phase 3
    consider(kWildernessTown4GatePos, std::string("Enter ") + kTown4Name);  // Phase 4: Cragmoor
    if (wasEngaged) { r.engaged = true; r.pos = s.wildEngaged->pos; }
    return r;
}

// UI rects the orbit input must ignore (mirrors Town3DPointInUI for the
// wilderness HUD: the 3D/2D toggle, tap-to-interact, the virtual joystick,
// and the live-combat UI while engaged).
static Rectangle JournalPanelRect();      // defined with the journal UI below
static Rectangle JournalWildButtonRect(); // defined with the journal UI below
static bool CorpseUIPointIn(Vector2 m);
static bool Wild3DPointInUI(Vector2 m, const GameState& s) {
    if (ExploreMenuPointInUI(m, s)) return true; // MENU toggle + dropdown
    if (CorpseUIPointIn(m)) return true;         // corpse window / Loot button
    if (CheckCollisionPointRec(m, { 452, 120, 68, 30 })) return true; // 3D/2D toggle
    if (CheckCollisionPointRec(m, { 528, 120, 96, 30 })) return true; // camera mode button
    if (CheckCollisionPointRec(m, { kViewport.x + kViewport.width - 150.0f,
                                    kViewport.y + kViewport.height - 90.0f, 130.0f, 60.0f })) return true; // tap-to-interact
    if (g_touchSeen && CheckCollisionPointRec(m, TargetButtonRect())) return true; // TARGET button
    if (s.worldMapOpen) return true; // full map: any tap closes it
    if (s.minimapOpen && CheckCollisionPointRec(m, MinimapRect())) return true; // minimap (tap opens the full map)
    if (!s.minimapOpen && CheckCollisionPointRec(m, MinimapToggleRect())) return true; // MAP button
    if (CheckCollisionPointRec(m, kJoystickZone)) return true;
    if (CheckCollisionPointRec(m, JournalWildButtonRect())) return true; // LOG button
    if (s.journalOpen && CheckCollisionPointRec(m, JournalPanelRect())) return true; // journal panel
    if (s.recallPickerOpen && CheckCollisionPointRec(m, RecallPickerRect())) return true; // recall modal
    if (s.wildEngaged.has_value()) {
        if (CheckCollisionPointRec(m, { 20, 110, 330, 60 })) return true; // HP/mana strip
        if (CheckCollisionPointRec(m, { 160, kViewport.y + kViewport.height - 160.0f, 330, 55 })) return true; // quick items
        if (CheckCollisionPointRec(m, { 160, kViewport.y + kViewport.height - 100.0f, 580, 100 })) return true; // spell hotbar
    }
    return false;
}

static void DrawWilderness3DWorld(GameState& s, int screenW, int screenH, const std::string& prompt) {
    T3DGroundHook groundHook_(WildGroundY); // rolling hills: everything drawn here sits on the terrain
    Vector2 mouse = GetMousePosition();

    // --- Camera input: follow mode (fixed Diablo-style angle) or free orbit ---
    // C key or the HUD camera button toggles; pinch zooms on touch. In follow
    // mode drags don't orbit; wheel/pinch zoom always works.
    if (IsKeyPressed(KEY_C)) g_t3dFollowMode = !g_t3dFollowMode;
    Town3DPinchZoom(kWild3DDistMin, kWild3DDistMax);
    // --- Orbit / zoom input (same feel as the town 3D view; the orbit state is
    // shared). No click-picking in Phase 1 - interaction stays walk-up + E / tap,
    // exactly like the 2D wilderness.
    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT) &&
        CheckCollisionPointRec(mouse, kViewport) && !Wild3DPointInUI(mouse, s)) {
        g_t3dOrbiting = true;
        g_t3dLastMouse = mouse;
        g_t3dDragDist = 0.0f;
    }
    if (g_t3dOrbiting && IsMouseButtonDown(MOUSE_BUTTON_LEFT)) {
        Vector2 d = { mouse.x - g_t3dLastMouse.x, mouse.y - g_t3dLastMouse.y };
        g_t3dLastMouse = mouse;
        g_t3dDragDist += fabsf(d.x) + fabsf(d.y);
        if (!g_t3dFollowMode) {
            g_t3dYaw -= d.x * 0.006f; // unbounded; the smoothed yaw follows continuously
            g_t3dPitch = std::clamp(g_t3dPitch + d.y * 0.005f, kT3DPitchMin, kT3DPitchMax);
        }
    }
    if (IsMouseButtonReleased(MOUSE_BUTTON_LEFT) && g_t3dOrbiting) {
        // Tap-to-flag (2026-09-24): a tap that wasn't a drag picks a monster the
        // same way the 2D click does - flagging it for auto-approach.
        bool wasClick = g_t3dDragDist < 8.0f;
        g_t3dOrbiting = false;
        if (wasClick && CheckCollisionPointRec(mouse, kViewport) && !Wild3DPointInUI(mouse, s)) {
            Town3DCam pc = Wild3DGetCam(s, screenW, screenH);
            Wild3DPickFlag(s, pc, mouse);
        }
    }
    if (!IsMouseButtonDown(MOUSE_BUTTON_LEFT)) g_t3dOrbiting = false;
    float wheel = GetMouseWheelMove();
    if (wheel != 0.0f && CheckCollisionPointRec(mouse, kViewport) && !Wild3DPointInUI(mouse, s))
        g_t3dDist = std::clamp(g_t3dDist * (1.0f - wheel * 0.12f), kWild3DDistMin, kWild3DDistMax);

    // --- 3D scene: sky, then the lit + shadowed wilderness ---
    Town3DEnsureShadow();
    Wild3DLoadModels();
    Wild3DEnsureGround();
    Wild3DBuildScatter();
    Town3DCam c = Wild3DGetCam(s, screenW, screenH);
    T3DApplyShake(c); // combat camera kick (hit / hurt), zero when idle
    g_hudCam = c; g_hudCamZone = 0;
    Camera3D cam3d = { c.pos, c.target, { 0, 1, 0 }, c.fovY, CAMERA_PERSPECTIVE };
    T3DUpdateDayNight(s.worldTime, false); // time of day: sun, sky, fog colors
    BeginMode3D(cam3d);
    Wild3DDrawSky(c.pos); // gradient sky, default shader (unlit, unfogged)
    // Per-frame shader state, same as the town pass: just the camera position
    // for specular/fog (see Town3DEnsureLit - no shadow map in this system).
    Town3DEnsureLit();
    if (g_t3dLit.ready) SetShaderValue(g_t3dLit.shader, g_t3dLit.viewPosLoc, &c.pos, SHADER_UNIFORM_VEC3);
    T3DUpdateViewFog(c);
    T3DGrassFrameUpdate(c.pos); // sway clock for the grass shader
    Wild3DDrawSceneContents(s, false, &c);
    Wild3DDrawAmbience(c); // birds, unlit, one batched draw call, main pass only
    T3DDrawLife(c, s.wildernessPlayerPos, 1, 0, g_t3dNight, s.wildernessPlayerPos.y < 700.0f); // butterflies, leaves, ground birds
    // Combat FX (2026-09-24): flag marker, spell projectiles/impacts, heal +
    // vigor auras, summoned fiend - world-space, so they sit in the scene.
    DrawFlagMarker3D(s, 0);
    DrawSpellFX3D(s, 0);
    DrawHitSparks3D(0, cam3d);
    // Nearest-interactable ring (warm) + red ring on the engaged monster.
    Wild3DNearest nearest = Wild3DNearestInfo(s);
    bool inRange = nearest.valid && nearest.dist < kNodeRadius + kInteractRange;
    {
        float pulse = 0.60f + 0.18f * sinf((float)GetTime() * 4.0f);
        if (nearest.engaged)
            Town3DDrawGroundRing(nearest.pos.x, nearest.pos.y, 3.0f, 46.0f, 56.0f, 36,
                                 Fade(Color{ 255, 80, 60, 255 }, pulse));
        else if (inRange)
            Town3DDrawGroundRing(nearest.pos.x, nearest.pos.y, 3.0f, 52.0f, 62.0f, 36,
                                 Fade(Color{ 255, 196, 110, 255 }, pulse));
    }
    EndMode3D();
    T3DDrawVignette();

    // --- 2D overlay: gate/entrance labels (distance-faded like the town's) ---
    {
        const float fadeNear = 1200.0f, fadeFar = 2400.0f;
        auto label3D = [&](float x, float y, float z, const std::string& text) {
            Vector2 sp;
            if (!Town3DProject(c, { x, y + GroundY(x, z), z }, &sp)) return; // on the hills
            if (sp.x < -60 || sp.x > screenW + 60 || sp.y < 100 || sp.y > screenH) return;
            float bd = hypotf(c.pos.x - x, c.pos.z - z);
            float a = std::clamp((fadeFar - bd) / (fadeFar - fadeNear), 0.0f, 1.0f);
            if (a < 0.03f) return;
            int fsz = (int)(11.0f + 3.0f * a);
            int w = MeasureUIText(text.c_str(), fsz);
            int sx = (int)(sp.x - w / 2), sy = (int)(sp.y - fsz);
            DrawRectangle(sx - 4, sy - 2, w + 8, fsz + 5, Fade(BLACK, 0.55f * a));
            DrawUIText(text.c_str(), sx, sy, fsz, Fade(WHITE, a));
        };
        label3D(kWildernessReturnGatePos.x, 110, kWildernessReturnGatePos.y, "Emberhold Gate");
        label3D(kWildernessTown2GatePos.x, 110, kWildernessTown2GatePos.y, kTown2Name);
        label3D(kWildernessTown3GatePos.x, 110, kWildernessTown3GatePos.y, kTown3Name);
        label3D(kWildernessTown4GatePos.x, 110, kWildernessTown4GatePos.y, kTown4Name); // Phase 4
        label3D(kOrcFortPos.x + cosf(kOrcFortGateYaw) * kOrcFortRadius, 170, kOrcFortPos.y + sinf(kOrcFortGateYaw) * kOrcFortRadius, "Grimtusk Hold");
        for (const WildernessDungeonEntrance& e : kWildernessDungeonEntrances)
            label3D(e.pos.x, 110, e.pos.y, kDungeons[e.dungeonIdx].name);
        for (size_t pi = 0; pi < kHousePlots.size(); pi++) {
            const HousePlot& hp = kHousePlots[pi];
            if ((int)pi == s.housePlotIdx) {
                std::string hn = s.houseName.empty() ? "Homestead" : s.houseName;
                if (g_houseSignPos.y > 0) label3D(g_houseSignPos.x, 64, g_houseSignPos.z, hn); // over the sign post
                else label3D(hp.pos.x, 130, hp.pos.y, hn);
            } else {
                label3D(hp.pos.x, 110, hp.pos.y, "Plot for Sale - " + std::to_string(hp.price) + "g");
            }
        }
        if (inRange && !nearest.engaged)
            label3D(nearest.pos.x, 80, nearest.pos.y, nearest.label);
    }
    // Interaction prompt (the 2D view draws it via DrawPlayer; the 3D view has no
    // player sprite call, so it goes here, same style as the town 3D prompt).
    if (!prompt.empty()) {
        int w = MeasureUIText(prompt.c_str(), 14);
        int sx = (int)(screenW - w) / 2, sy = screenH - 96;
        DrawRectangle(sx - 6, sy - 3, w + 12, 22, Fade(BLACK, 0.55f));
        DrawUIText(prompt.c_str(), sx, sy, 14, WHITE);
    }
    DrawFloatTexts3D(s, c, 0, screenW, screenH); // combat feel: damage numbers / MISS
    DrawGuildTags3D(s, c, screenW, screenH);     // rival/Murder Inc. names, activity, speech
    DrawUIText("3D view: drag to orbit, wheel to zoom. [V] toggles 2D.", 20, 196, 12,
               Color{ 90, 74, 52, 255 });
    // Phase 0: HUD region label (3D view) - same top-center pill as the 2D view,
    // computed live from the player position so it flips at boundaries.
    {
        const char* regionName = RegionName(RegionAt(s.wildernessPlayerPos));
        int w = MeasureUIText(regionName, 16);
        int sx = (int)(screenW - w) / 2;
        DrawRectangle(sx - 10, 106, w + 20, 26, Fade(BLACK, 0.45f));
        DrawUIText(regionName, sx, 110, 16, Color{ 232, 200, 120, 255 });
    }
}


// ---------------------------------------------------------------------
// 3D dungeon view (2026-09-24, Phase 2 - dungeons 3D). One 3D view per
// dungeon, built from the same 2D data the classic view uses: wall geometry
// is extruded from the kDungeonRoomLayouts rectangles (anything not floor is
// wall, exactly like DungeonIsFloor), floors are baked per-dungeon from the
// themed 2D tiles, and torches sit in the big rooms. Lighting is a custom
// torchlight shader (assets/shaders/torchlight.*): dark ambient + up to 8
// warm flickering point lights - no sun, no shadowmaps indoors. Pure view
// layer: positions, transitions, and combat all stay in DrawHuntScreen.
// ---------------------------------------------------------------------
static const float kDung3DDistMin = 150.0f;  // closest zoom: one room fills the view
static const float kDung3DDistMax = 700.0f;  // farthest zoom: most of the dungeon in frame
static const float kDung3DWallH = 100.0f;    // extruded wall height
static const float kDung3DCell = 45.0f;      // wall-scan grid cell (1800/45 = 40)
static const int kDung3DGridN = 40;
static const int kDung3DGroundPx = 1024;     // baked floor texture resolution
static const int kDung3DMaxTorches = 8;      // torchlight shader light count
static const Vector2 kDung3DExitPos = { 900, 1300 }; // mirrors DrawHuntScreen's kDungeonExitPos

// Torch-light shader + baked flame sprite (both one-time).
struct Dungeon3DTorch {
    bool ready = false;
    bool tried = false;
    Shader shader{};
    int torchPosLoc = -1, torchCountLoc = -1, timeLoc = -1, ambientLoc = -1;
    Texture2D flameTex{};
};
static Dungeon3DTorch g_dung3dTorch;

static void Dungeon3DEnsureTorch() {
    Dungeon3DTorch& T = g_dung3dTorch;
    if (T.ready || T.tried) return;
    T.tried = true;
    T.shader = LoadShader("assets/shaders/torchlight.vs", "assets/shaders/torchlight.fs");
    if (T.shader.id == 0) return; // missing shader files: fall back to flat lighting below
    T.torchPosLoc = GetShaderLocation(T.shader, "torchPos");
    T.torchCountLoc = GetShaderLocation(T.shader, "torchCount");
    T.timeLoc = GetShaderLocation(T.shader, "time");
    T.ambientLoc = GetShaderLocation(T.shader, "ambient");
    // Cool dark ambient - the torches do the work. Linear-space value since the
    // 2026-09-25 gamma fix in torchlight.fs (0.30 there read far brighter).
    float amb[4] = { 0.17f, 0.16f, 0.21f, 1.0f };
    SetShaderValue(T.shader, T.ambientLoc, amb, SHADER_UNIFORM_VEC4);
    // Procedural flame sprite (no new assets): white-yellow core fading to
    // transparent orange, teardrop-narrowed toward the top. Drawn as a
    // camera-facing billboard at each torch, unlit.
    Image img = GenImageColor(64, 64, { 0, 0, 0, 0 });
    for (int y = 0; y < 64; y++) {
        for (int x = 0; x < 64; x++) {
            float dx = (x - 32) / 32.0f, dy = (y - 30) / 32.0f;
            float w = 1.0f - (y / 64.0f) * 0.45f;
            float d = sqrtf(dx * dx / (w * w) + dy * dy);
            if (d < 1.0f) {
                float a = 1.0f - d;
                Color c = { 255, (unsigned char)(120 + 135 * a), (unsigned char)(30 + 60 * a),
                            (unsigned char)(255 * a * a) };
                ImageDrawPixel(&img, x, y, c);
            }
        }
    }
    T.flameTex = LoadTextureFromImage(img);
    UnloadImage(img);
    SetTextureFilter(T.flameTex, TEXTURE_FILTER_BILINEAR);
    T.ready = true;
}

// Assign the torch shader to a model's materials - required, not optional:
// DrawModel enables the MATERIAL's shader, so a bare rlEnableShader before
// DrawModel would be overridden (same reason Town3DApplyLitShader exists).
static void Dungeon3DApplyTorchShader(Model& m) {
    Dungeon3DEnsureTorch();
    if (!g_dung3dTorch.ready || m.meshCount <= 0) return;
    for (int i = 0; i < m.materialCount; i++) m.materials[i].shader = g_dung3dTorch.shader;
}

// Torch positions: one per big room (corridors are too narrow for a pole),
// from kDungeonRoomLayouts; rect 0 is always the entrance room. Offset
// slightly off the room center so the pole doesn't sit exactly on the
// monster's wander node there.
static void Dungeon3DTorchSpots(int dungeonIdx, Vector3* out, int* outCount) {
    int n = 0;
    for (const Rectangle& r : kDungeonRoomLayouts[dungeonIdx]) {
        if (n >= kDung3DMaxTorches) break;
        if (r.width * r.height < 50000.0f) continue; // corridor, skip
        out[n++] = { r.x + r.width * 0.5f + 70.0f, 0.0f, r.y + r.height * 0.5f + 40.0f };
    }
    *outCount = n;
}

// Baked dungeon floor: one 1024px texture over the 1800-unit world, stamped
// one tile per 45-unit cell - wall texture everywhere, themed floor texture
// where DungeonIsFloor, plus the same per-dungeon specials the 2D view draws
// (Sunken Crypt water pool, Hollow Warrens boss-room rug). One draw call.
struct Dungeon3DGround {
    bool loaded = false;
    int dungeon = -1;
    Texture2D tex{};
    Model model{};
};
static Dungeon3DGround g_dung3dGround;

static void Dungeon3DEnsureGround(int dungeonIdx) {
    Dungeon3DGround& G = g_dung3dGround;
    if (G.loaded && G.dungeon == dungeonIdx) return;
    if (G.loaded) { UnloadModel(G.model); UnloadTexture(G.tex); G.loaded = false; }
    const int SZ = kDung3DGroundPx;
    Image ground = GenImageColor(SZ, SZ, { 20, 18, 22, 255 });
    const float k = (float)SZ / kDungeonWorldSize; // px per world unit (v=0 at world z=0, like the town bake)
    const Texture2D* wallTex = ThemedDungeonWall(dungeonIdx);
    const Texture2D* floorTex = ThemedDungeonFloor(dungeonIdx);
    Image wallImg{}, floorImg{};
    bool wallOk = wallTex && wallTex->id > 0;
    bool floorOk = floorTex && floorTex->id > 0;
    if (wallOk) wallImg = LoadImageFromTexture(*wallTex);
    if (floorOk) floorImg = LoadImageFromTexture(*floorTex);
    const float cell = kDung3DCell;
    for (float wy = 0; wy < kDungeonWorldSize; wy += cell) {
        for (float wx = 0; wx < kDungeonWorldSize; wx += cell) {
            bool isFloor = DungeonIsFloor(dungeonIdx, { wx + cell * 0.5f, wy + cell * 0.5f });
            Rectangle dest = { wx * k, wy * k, cell * k + 1.0f, cell * k + 1.0f };
            if (isFloor && floorOk) {
                ImageDraw(&ground, floorImg, { 0, 0, (float)floorImg.width, (float)floorImg.height }, dest, WHITE);
            } else if (!isFloor && wallOk) {
                // Emberveil's lava wall/floor art reads as nearly identical (see the
                // 2D view's obsidian multiply tint) - same treatment here.
                // Phase 3: the Frostbound Tomb gets an icy tint on its crypt tiles.
                Color tint = (dungeonIdx == 3) ? Color{ 110, 85, 75, 255 } : // Ember Depths: cooled obsidian walls
                             (dungeonIdx == 4) ? Color{ 190, 215, 240, 255 } : WHITE; // Frostbound Tomb: icy
                ImageDraw(&ground, wallImg, { 0, 0, (float)wallImg.width, (float)wallImg.height }, dest, tint);
            } else {
                ImageDrawRectangle(&ground, (int)dest.x, (int)dest.y, (int)dest.width, (int)dest.height,
                                   isFloor ? Color{ 60, 50, 46, 255 } : Color{ 40, 40, 44, 255 });
            }
        }
    }
    // Sunken Crypt's flooded boss room - same rect the 2D view tiles water over.
    if (dungeonIdx == 0 && g_assets.sunkenCryptWaterOk) { // Whisper Crypt's flooded boss room
        Image wimg = LoadImageFromTexture(g_assets.sunkenCryptWater);
        for (float wy = 1260; wy < 1600; wy += 32)
            for (float wx = 1260; wx < 1600; wx += 32)
                ImageDraw(&ground, wimg, { 0, 0, 32, 14 }, { wx * k, wy * k, 32 * k, 32 * k }, WHITE);
        UnloadImage(wimg);
    }
    // Hollow Warrens' medallion rug in its boss room - same rect as the 2D view.
    if (dungeonIdx == 5 && g_assets.hollowWarrensRugOk) { // The Hollow's boss-room rug
        Image rimg = LoadImageFromTexture(g_assets.hollowWarrensRug);
        ImageDraw(&ground, rimg, { 0, 0, (float)rimg.width, (float)rimg.height },
                          { 680 * k, 240 * k, 440 * k, 400 * k }, WHITE);
        UnloadImage(rimg);
    }
    if (wallOk) UnloadImage(wallImg);
    if (floorOk) UnloadImage(floorImg);
    G.tex = LoadTextureFromImage(ground);
    UnloadImage(ground);
    GenTextureMipmaps(&G.tex);
    SetTextureFilter(G.tex, TEXTURE_FILTER_TRILINEAR);
    G.model = LoadModelFromMesh(GenMeshPlane(kDungeonWorldSize, kDungeonWorldSize, 1, 1));
    G.model.materials[0].maps[MATERIAL_MAP_DIFFUSE].texture = G.tex;
    Dungeon3DApplyTorchShader(G.model); // DrawModel needs the shader on the material
    G.dungeon = dungeonIdx;
    G.loaded = true;
}

// Dungeon walls: one merged mesh extruded from the 2D floor test. The 1800-unit
// world is scanned on a 45-unit grid; a cell is wall when DungeonIsFloor is
// false there but true in a neighbor - so room openings/corridors come out
// exactly where the 2D collision says floor is. Top faces for every wall cell,
// side faces only toward floor neighbors: one model, one draw call.
struct Dungeon3DWalls {
    bool loaded = false;
    int dungeon = -1;
    Model model{};
};
static Dungeon3DWalls g_dung3dWalls;

static void Dungeon3DBuildWalls(int dungeonIdx) {
    Dungeon3DWalls& W = g_dung3dWalls;
    if (W.loaded && W.dungeon == dungeonIdx) return;
    if (W.loaded) { UnloadModel(W.model); W.loaded = false; }
    const int N = kDung3DGridN;
    const float cell = kDung3DCell;
    const float wallH = kDung3DWallH;
    std::vector<char> isFloor(N * N, 0);
    for (int gz = 0; gz < N; gz++)
        for (int gx = 0; gx < N; gx++)
            isFloor[gz * N + gx] = DungeonIsFloor(dungeonIdx, { (gx + 0.5f) * cell, (gz + 0.5f) * cell }) ? 1 : 0;
    auto at = [&](int gx, int gz) -> bool {
        if (gx < 0 || gz < 0 || gx >= N || gz >= N) return false; // outside the world: solid
        return isFloor[gz * N + gx] != 0;
    };
    struct DWVert { float x, y, z, nx, ny, nz, u, v; };
    std::vector<DWVert> verts;
    std::vector<unsigned short> idx;
    const float tileW = 90.0f; // world units per wall-texture repeat
    auto quad = [&](DWVert a, DWVert b, DWVert c, DWVert d) {
        unsigned short base = (unsigned short)verts.size();
        verts.push_back(a); verts.push_back(b); verts.push_back(c); verts.push_back(d);
        idx.push_back(base); idx.push_back(base + 1); idx.push_back(base + 2);
        idx.push_back(base); idx.push_back(base + 2); idx.push_back(base + 3);
    };
    for (int gz = 0; gz < N; gz++) {
        for (int gx = 0; gx < N; gx++) {
            if (at(gx, gz)) continue;
            // Only cells touching floor get geometry - deeper rock is invisible.
            bool touches = at(gx - 1, gz - 1) || at(gx, gz - 1) || at(gx + 1, gz - 1) ||
                           at(gx - 1, gz) || at(gx + 1, gz) ||
                           at(gx - 1, gz + 1) || at(gx, gz + 1) || at(gx + 1, gz + 1);
            if (!touches) continue;
            float x0 = gx * cell, x1 = (gx + 1) * cell, z0 = gz * cell, z1 = (gz + 1) * cell;
            // Top face (CCW from above). Side faces only toward floor neighbors
            // (CCW from outside); winding verified against ((b-a)x(c-a)).n > 0.
            quad({ x0, wallH, z1, 0, 1, 0, x0 / tileW, z1 / tileW },
                 { x1, wallH, z1, 0, 1, 0, x1 / tileW, z1 / tileW },
                 { x1, wallH, z0, 0, 1, 0, x1 / tileW, z0 / tileW },
                 { x0, wallH, z0, 0, 1, 0, x0 / tileW, z0 / tileW });
            if (at(gx, gz - 1))
                quad({ x1, 0, z0, 0, 0, -1, x1 / tileW, 0 },
                     { x0, 0, z0, 0, 0, -1, x0 / tileW, 0 },
                     { x0, wallH, z0, 0, 0, -1, x0 / tileW, wallH / tileW },
                     { x1, wallH, z0, 0, 0, -1, x1 / tileW, wallH / tileW });
            if (at(gx, gz + 1))
                quad({ x0, 0, z1, 0, 0, 1, x0 / tileW, 0 },
                     { x1, 0, z1, 0, 0, 1, x1 / tileW, 0 },
                     { x1, wallH, z1, 0, 0, 1, x1 / tileW, wallH / tileW },
                     { x0, wallH, z1, 0, 0, 1, x0 / tileW, wallH / tileW });
            if (at(gx - 1, gz))
                quad({ x0, 0, z0, -1, 0, 0, z0 / tileW, 0 },
                     { x0, 0, z1, -1, 0, 0, z1 / tileW, 0 },
                     { x0, wallH, z1, -1, 0, 0, z1 / tileW, wallH / tileW },
                     { x0, wallH, z0, -1, 0, 0, z0 / tileW, wallH / tileW });
            if (at(gx + 1, gz))
                quad({ x1, 0, z1, 1, 0, 0, z1 / tileW, 0 },
                     { x1, 0, z0, 1, 0, 0, z0 / tileW, 0 },
                     { x1, wallH, z0, 1, 0, 0, z1 / tileW, wallH / tileW },
                     { x1, wallH, z1, 1, 0, 0, z1 / tileW, wallH / tileW });
        }
    }
    if (verts.empty() || verts.size() > 60000) return; // shouldn't happen; stay safe
    Mesh mesh = { 0 };
    mesh.vertexCount = (int)verts.size();
    mesh.triangleCount = (int)idx.size() / 3;
    mesh.vertices = (float*)malloc(verts.size() * 3 * sizeof(float));
    mesh.normals = (float*)malloc(verts.size() * 3 * sizeof(float));
    mesh.texcoords = (float*)malloc(verts.size() * 2 * sizeof(float));
    mesh.colors = (unsigned char*)malloc(verts.size() * 4);
    mesh.indices = (unsigned short*)malloc(idx.size() * sizeof(unsigned short));
    // Emberveil's lava wall art reads as nearly identical to its floor (see the 2D
    // view's obsidian multiply tint) - same treatment here, via vertex colors.
    unsigned char tr = 255, tg = 255, tb = 255;
    if (dungeonIdx == 3) { tr = 150; tg = 120; tb = 105; } // Ember Depths: obsidian vertex tint
    for (size_t i = 0; i < verts.size(); i++) {
        const DWVert& v = verts[i];
        mesh.vertices[i * 3] = v.x; mesh.vertices[i * 3 + 1] = v.y; mesh.vertices[i * 3 + 2] = v.z;
        mesh.normals[i * 3] = v.nx; mesh.normals[i * 3 + 1] = v.ny; mesh.normals[i * 3 + 2] = v.nz;
        mesh.texcoords[i * 2] = v.u; mesh.texcoords[i * 2 + 1] = v.v;
        mesh.colors[i * 4] = tr; mesh.colors[i * 4 + 1] = tg; mesh.colors[i * 4 + 2] = tb; mesh.colors[i * 4 + 3] = 255;
        // Wall tops read as near-black void (2026-09-26), Diablo-style: from the
        // follow camera, textured tops looked like more floor and swamped the
        // screen; dark tops make every room's shape read at a glance.
        if (v.ny > 0.5f) { mesh.colors[i * 4] = 14; mesh.colors[i * 4 + 1] = 12; mesh.colors[i * 4 + 2] = 16; }
    }
    for (size_t i = 0; i < idx.size(); i++) mesh.indices[i] = idx[i];
    UploadMesh(&mesh, false);
    W.model = LoadModelFromMesh(mesh);
    const Texture2D* wallTex = ThemedDungeonWall(dungeonIdx);
    if (wallTex && wallTex->id > 0) {
        SetTextureWrap(*wallTex, TEXTURE_WRAP_REPEAT);
        W.model.materials[0].maps[MATERIAL_MAP_DIFFUSE].texture = *wallTex;
    } else {
        W.model.materials[0].maps[MATERIAL_MAP_DIFFUSE].color = Color{ 90, 85, 95, 255 };
    }
    Dungeon3DApplyTorchShader(W.model); // DrawModel needs the shader on the material
    W.dungeon = dungeonIdx;
    W.loaded = true;
}

// ---- Dungeon dressing: KayKit props along the walls (2026-09-26) ----
// The 3D dungeons were bare extruded boxes. This places KayKit Dungeon
// Remastered props (assets/dungeon_props, CC0) against the wall faces, themed
// per dungeon: crates and kegs in the raider nest, pillars/candles/broken arms
// in the crypts, banners in each dungeon's color. Purely visual - nothing here
// touches collision (DungeonIsFloor stays the only walkability test), so props
// are kept tight to the walls, out of corridors and doorways, and clear of the
// torch poles and the entrance/exit, where the player and monsters actually
// move. Placement runs on the same 45-unit grid the wall mesh is extruded
// from, so every prop sits against a real wall face. It is deterministic per
// dungeon (hash of cell + side), built once like the walls, and costs one
// DrawModelEx per prop (a few dozen per dungeon).
enum DungeonPropId {
    kDPBarrel, kDPBarrelStack, kDPBox, kDPBoxStack, kDPCrates, kDPKeg, kDPTrunk,
    kDPTableBroken, kDPBedroll, kDPRubbleHalf, kDPRubbleLarge, kDPCandles, kDPPillar,
    kDPShelves, kDPShelfCandles, kDPSwordShield,
    kDPBannerWhite, kDPBannerGreen, kDPBannerBlue, kDPBannerRed, kDPBannerBrown, kDPBannerYellow,
    kDPCount
};
struct DungeonPropDef {
    const char* file;
    bool wall;      // wall-mounted: back pressed to the wall face, lifted to mountY
    float scaleMul; // on top of kDung3DPropScale
    float mountY;   // wall props: lift in kit units
};
static const DungeonPropDef kDungeonPropDefs[kDPCount] = {
    { "barrel_large", false, 0.85f, 0.0f },
    { "barrel_small_stack", false, 1.0f, 0.0f },
    { "box_large", false, 1.0f, 0.0f },
    { "box_stacked", false, 0.55f, 0.0f },
    { "crates_stacked", false, 0.75f, 0.0f },
    { "keg", false, 0.85f, 0.0f },
    { "trunk_medium_A", false, 1.1f, 0.0f },
    { "table_medium_broken", false, 0.85f, 0.0f },
    { "bed_floor", false, 1.0f, 0.0f },
    { "rubble_half", false, 0.45f, 0.0f },
    { "rubble_large", false, 0.30f, 0.0f },
    { "candle_triple", false, 1.3f, 0.0f },
    { "pillar_decorated", false, 0.7f, 0.0f },
    { "shelves", true, 1.0f, 0.0f },
    { "shelf_small_candles", true, 1.3f, 1.6f },
    { "sword_shield_broken", true, 1.2f, 1.7f },
    { "banner_patternA_white", true, 1.0f, 0.0f },
    { "banner_patternA_green", true, 1.0f, 0.0f },
    { "banner_patternA_blue", true, 1.0f, 0.0f },
    { "banner_patternA_red", true, 1.0f, 0.0f },
    { "banner_patternA_brown", true, 1.0f, 0.0f },
    { "banner_patternA_yellow", true, 1.0f, 0.0f },
};
// KayKit walls are 4 kit units tall; ours are kDung3DWallH (100), so 25 keeps
// the pack's own proportions against our walls and the ~60-unit characters.
static const float kDung3DPropScale = 25.0f;

// Per-dungeon theme: floor clutter pool, wall-mounted pool, banner color.
struct DungeonPropTheme { std::vector<int> floor; std::vector<int> wall; int banner; };
static const DungeonPropTheme kDungeonPropThemes[6] = {
    // [0] Whisper Crypt: old tomb - rubble, candles, fallen arms, white banners
    { { kDPRubbleHalf, kDPRubbleLarge, kDPCandles, kDPCandles, kDPTrunk, kDPBarrel },
      { kDPSwordShield, kDPShelfCandles, kDPShelves }, kDPBannerWhite },
    // [1] Weavers' Nest: raider stronghold - supplies, bedrolls, broken tables
    { { kDPCrates, kDPBoxStack, kDPBarrel, kDPKeg, kDPBedroll, kDPTableBroken, kDPBox, kDPBarrelStack },
      { kDPShelves, kDPSwordShield }, kDPBannerGreen },
    // [2] Sunken Vault: flooded cave vault - washed-up cargo and collapse
    { { kDPBarrelStack, kDPBox, kDPRubbleHalf, kDPTrunk, kDPBarrel, kDPRubbleLarge },
      { kDPShelves }, kDPBannerBlue },
    // [3] Ember Depths: volcanic forge - kegs, crates, slag rubble, spent arms
    { { kDPKeg, kDPBarrel, kDPCrates, kDPRubbleHalf, kDPBox, kDPRubbleLarge },
      { kDPSwordShield, kDPShelves }, kDPBannerRed },
    // [4] Frostbound Tomb: frozen royal crypt - candles, fallen arms, rubble
    { { kDPCandles, kDPRubbleHalf, kDPCandles, kDPTrunk, kDPRubbleLarge },
      { kDPSwordShield, kDPShelfCandles }, kDPBannerBlue },
    // [5] The Hollow: lightless abyss - collapse and a few old candles
    { { kDPRubbleHalf, kDPRubbleLarge, kDPCandles, kDPBarrel, kDPTrunk },
      { kDPShelfCandles, kDPShelves }, kDPBannerYellow },
};

struct DungeonPropInst { int id; Vector3 pos; float yawDeg; float scale; };
struct Dungeon3DProps {
    bool modelsTried = false;
    Model models[kDPCount]{};
    bool ok[kDPCount]{};
    BoundingBox bb[kDPCount]{};
    int dungeon = -1;
    std::vector<DungeonPropInst> inst;
};
static Dungeon3DProps g_dung3dProps;

static float Dungeon3DPropHash(int a, int b, int c) {
    unsigned int h = (unsigned int)a * 73856093u ^ (unsigned int)b * 19349663u ^ (unsigned int)c * 83492791u;
    h ^= h >> 13; h *= 0x5bd1e995u; h ^= h >> 15;
    return (h & 0xFFFFu) / 65535.0f;
}

static void Dungeon3DBuildProps(int dungeonIdx) {
    Dungeon3DProps& P = g_dung3dProps;
    if (!P.modelsTried) {
        P.modelsTried = true;
        for (int i = 0; i < kDPCount; i++) {
            const char* path = TextFormat("assets/dungeon_props/%s.glb", kDungeonPropDefs[i].file);
            if (!FileExists(path)) continue; // missing asset: that prop is simply skipped
            P.models[i] = LoadModel(path);
            P.ok[i] = P.models[i].meshCount > 0;
            if (!P.ok[i]) continue;
            P.bb[i] = GetModelBoundingBox(P.models[i]);
            Dungeon3DApplyTorchShader(P.models[i]);
        }
    }
    if (P.dungeon == dungeonIdx) return;
    P.dungeon = dungeonIdx;
    P.inst.clear();
    if (dungeonIdx < 0 || dungeonIdx >= 6) return;
    const DungeonPropTheme& theme = kDungeonPropThemes[dungeonIdx];
    const int N = kDung3DGridN;
    const float cell = kDung3DCell, half = kDung3DCell * 0.5f;
    auto floorAt = [&](int gx, int gz) -> bool {
        if (gx < 0 || gz < 0 || gx >= N || gz >= N) return false;
        return DungeonIsFloor(dungeonIdx, { (gx + 0.5f) * cell, (gz + 0.5f) * cell });
    };
    // Rooms only: a cell inside any corridor rect (the small connectors) stays
    // bare, so passages never get narrower than they look in 2D.
    auto inRoom = [&](Vector2 p) -> bool {
        bool room = false;
        for (const Rectangle& r : kDungeonRoomLayouts[dungeonIdx]) {
            if (p.x < r.x || p.x > r.x + r.width || p.y < r.y || p.y > r.y + r.height) continue;
            if (r.width * r.height < 50000.0f) return false;
            room = true;
        }
        return room;
    };
    Vector3 torches[kDung3DMaxTorches];
    int torchCount = 0;
    Dungeon3DTorchSpots(dungeonIdx, torches, &torchCount);
    auto dist = [](Vector2 a, Vector2 b) { return sqrtf((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y)); };
    auto clearOf = [&](Vector2 p) -> bool {
        if (dist(p, kDung3DExitPos) < 120.0f) return false; // entrance/exit + spawn
        for (int i = 0; i < torchCount; i++)
            if (dist(p, { torches[i].x, torches[i].z }) < 75.0f) return false;
        return true;
    };
    // face: point on the wall face; n: unit normal pointing into the room.
    auto addProp = [&](int id, Vector2 face, Vector2 n, float jitterDeg) {
        if (!P.ok[id]) return;
        const DungeonPropDef& d = kDungeonPropDefs[id];
        float sc = kDung3DPropScale * d.scaleMul;
        float yaw = atan2f(n.x, n.y) * RAD2DEG + jitterDeg; // model +Z faces into the room
        float off;
        if (d.wall) {
            // Back of the model (its min Z) pressed against the face, 0.5 off it.
            off = 0.5f - P.bb[id].min.z * sc;
        } else {
            // Pull the footprint's radius off the wall so nothing clips into it.
            const BoundingBox& b = P.bb[id];
            float r = fmaxf(fmaxf(fabsf(b.min.x), fabsf(b.max.x)), fmaxf(fabsf(b.min.z), fabsf(b.max.z))) * sc;
            off = fminf(r, 34.0f) + 2.0f;
        }
        P.inst.push_back({ id, { face.x + n.x * off, d.mountY * sc, face.y + n.y * off }, yaw, sc });
    };
    const int dx[4] = { 1, -1, 0, 0 }, dz[4] = { 0, 0, 1, -1 };
    for (int gz = 0; gz < N; gz++) {
        for (int gx = 0; gx < N; gx++) {
            if (!floorAt(gx, gz)) continue;
            Vector2 c = { (gx + 0.5f) * cell, (gz + 0.5f) * cell };
            if (!inRoom(c) || !clearOf(c)) continue;
            // Inner corner: walls on two perpendicular sides -> a pillar.
            for (int a = 0; a < 2; a++) {
                for (int b = 2; b < 4; b++) {
                    if (floorAt(gx + dx[a], gz + dz[a]) || floorAt(gx + dx[b], gz + dz[b])) continue;
                    if (Dungeon3DPropHash(gx, gz, dungeonIdx * 7 + a * 2 + b) > 0.75f) continue;
                    Vector2 corner = { c.x + (dx[a] + dx[b]) * half, c.y + (dz[a] + dz[b]) * half };
                    Vector2 n = { -(float)(dx[a] + dx[b]) * 0.70711f, -(float)(dz[a] + dz[b]) * 0.70711f };
                    addProp(kDPPillar, { corner.x + n.x * 4.0f, corner.y + n.y * 4.0f }, n, 0.0f);
                }
            }
            // Straight wall runs: wall on side k here and on both lateral
            // neighbors (so never at a doorway or a corner).
            for (int k = 0; k < 4; k++) {
                if (floorAt(gx + dx[k], gz + dz[k])) continue;
                int px = dz[k], pz = dx[k]; // perpendicular
                if (!floorAt(gx + px, gz + pz) || !floorAt(gx - px, gz - pz)) continue;
                if (floorAt(gx + px + dx[k], gz + pz + dz[k]) || floorAt(gx - px + dx[k], gz - pz + dz[k])) continue;
                float h = Dungeon3DPropHash(gx, gz, dungeonIdx * 13 + k);
                float h2 = Dungeon3DPropHash(gz, gx, dungeonIdx * 31 + k + 5);
                Vector2 face = { c.x + dx[k] * half, c.y + dz[k] * half };
                Vector2 n = { -(float)dx[k], -(float)dz[k] };
                if (h < 0.18f) {
                    int id = (h2 < 0.6f || theme.wall.empty()) ? theme.banner
                                                               : theme.wall[(int)(h2 * 97.0f) % theme.wall.size()];
                    addProp(id, face, n, 0.0f);
                } else if (h < 0.60f && !theme.floor.empty()) {
                    int id = theme.floor[(int)(h2 * 97.0f) % theme.floor.size()];
                    addProp(id, face, n, (h2 - 0.5f) * 50.0f);
                }
            }
        }
    }
}

static void Dungeon3DDrawProps() {
    const Dungeon3DProps& P = g_dung3dProps;
    for (const DungeonPropInst& d : P.inst)
        DrawModelEx(P.models[d.id], d.pos, { 0.0f, 1.0f, 0.0f }, d.yawDeg, { d.scale, d.scale, d.scale }, WHITE);
}

// Interior camera: the shared damped orbit/follow rig with tighter zoom
// limits, clamped inside the dungeon so it can't leave through the outer rock.
// (Room walls can still occlude at very low zoom - the tight limits keep that
// rare; the player marker, torchlight, and labels stay readable regardless.)
static Town3DCam Dungeon3DGetCam(const GameState& s, int screenW, int screenH) {
    Town3DCam c = Town3DGetCamFor(s.dungeonPlayerPos, screenW, screenH, 2, kDung3DDistMin, kDung3DDistMax,
                                 kT3DFollowPitch);
    c.pos.x = std::clamp(c.pos.x, 40.0f, kDungeonWorldSize - 40.0f);
    c.pos.z = std::clamp(c.pos.z, 40.0f, kDungeonWorldSize - 40.0f);
    c.target.x = std::clamp(c.target.x, 40.0f, kDungeonWorldSize - 40.0f);
    c.target.z = std::clamp(c.target.z, 40.0f, kDungeonWorldSize - 40.0f);
    c.fwd = T3VNorm(T3VSub(c.target, c.pos));
    c.right = T3VNorm(T3VCross(c.fwd, { 0, 1, 0 }));
    c.up = T3VCross(c.right, c.fwd);
    return c;
}

static Color Dungeon3DMonsterColor(int dungeonIdx, bool boss) {
    static const Color cols[6] = {
        { 110, 125, 145, 255 }, // [0] The Whisper Crypt - drowned pale blue
        { 88, 62, 88, 255 },    // [1] The Weavers' Nest - spider chitin purple-brown (Phase 5)
        { 45, 110, 120, 255 },  // [2] The Sunken Vault - drowned sea-teal (Phase 2)
        { 190, 85, 35, 255 },   // [3] The Ember Depths - molten orange (Phase 4)
        { 165, 200, 235, 255 }, // [4] The Frostbound Tomb - glacier ice (Phase 3)
        { 85, 70, 115, 255 },   // [5] The Hollow - lightless violet (Phase 5)
    };
    Color c = cols[dungeonIdx % 6];
    return boss ? ColorBrightness(c, 0.3f) : c;
}

// Phase 3 procedural dungeon monster: per-dungeon body plan from the creature
// kit (humanoid for orcs/goblins/wraiths/skeletons, quadruped for beasts),
// with diagonal-pair trot, idle bob and head turns. `tint` is the per-dungeon
// palette color (boss brightened by the caller).
static void Dungeon3DDrawMonster(int dungeonIdx, int monsterIdx, int trackId, float x, float z,
                                 float yawRad, Color tint, float sizeMul,
                                 float attackT = -1.0f, float hurtT = -1.0f, float deathT = -1.0f) {
    T3CDunLook look = T3CDungeonMonsterLook(dungeonIdx, monsterIdx);
    T3CAnim a = T3CMakeAnim(trackId, x, z);
    float sm = sizeMul * look.scale;
    // Combat read (2026-09-24): lunge pose on attackT, white-hot then red flash
    // while hurtT is live (2026-09-25).
    Color c = CombatHitTint(hurtT, tint, Color{ 220, 90, 90, 255 });
    if (look.serpent) {
        T3CDrawSerpent(g_t3cQuads[10].parts, x, z, yawRad, sm, c, a, false, attackT);
    } else if (look.humanoid) {
        if (DrawHuman(trackId, x, z, yawRad, sm * 0.94f, CombatHitTint(hurtT, WHITE, Color{ 220, 90, 90, 255 }),
                      HumanOutfitForDungeonMonster(dungeonIdx, monsterIdx, tint),
                      HumanMonsterPose(a.move, attackT, hurtT, deathT, attackT >= 0.0f || hurtT >= 0.0f), false))
            return;
        if (deathT >= 0.0f) sm *= std::max(0.05f, 1.0f - deathT);
        T3CDrawHumanoid(g_t3cHumans[look.humanIdx].parts, x, z, yawRad, sm, c,
                        ColorBrightness(tint, -0.45f), Color{ 200, 170, 140, 255 }, a, false,
                        attackT, -1.0f);
    } else {
        T3CDrawQuad(g_t3cQuads[look.specIdx].parts, x, z, yawRad, sm, c, a, 0.0f, false, attackT);
    }
}

static void Dungeon3DDrawPlayer(const GameState& s) {
    float x = s.dungeonPlayerPos.x, z = s.dungeonPlayerPos.y;
    float yaw = atan2f(s.playerFacing.y, s.playerFacing.x);
    T3CAnim a = T3CMakeAnim(kT3CTrackPlayerDungeon, x, z);
    Vector2 foe = s.dungeonEngaged.has_value() ? s.dungeonEngaged->pos : Vector2{ 0, 0 };
    if (DrawPlayerHuman(s, kT3CTrackPlayerDungeon, x, z, yaw, a.move, s.dungeonEngaged.has_value() ? &foe : nullptr,
                        false)) {
        // animated body drawn
    } else if (s.playerDeathAnimT > 0.0f) {
        float pshrink = std::max(0.05f, s.playerDeathAnimT / kPlayerDeathAnimTime);
        T3CDrawHumanoid(g_t3cHumans[2].parts, x, z, yaw, pshrink,
                        Color{ 100, 130, 185, 255 }, Color{ 55, 60, 75, 255 },
                        Color{ 225, 200, 165, 255 }, a, false);
    } else if (s.playerIsGhost) {
        Color g = Fade(Color{ 170, 205, 255, 255 }, 0.45f);
        T3CDrawHumanoid(g_t3cHumans[2].parts, x, z, yaw, 1.0f,
                        g, g, Fade(Color{ 220, 235, 255, 255 }, 0.45f), a, false);
    } else {
        // Combat read (2026-09-24): swing/cast poses ride the engaged monster's
        // timers; the player flashes red and reels on playerHurtT.
        float pAtk = -1.0f, pCast = -1.0f;
        PlayerCombatPhases3D(s, &pAtk, &pCast);
        Color shirt = Color{ 100, 130, 185, 255 };
        float px = x, pz = z;
        if (s.playerHurtT >= 0.0f) {
            shirt = Color{ 220, 90, 90, 255 };
            if (s.dungeonEngaged.has_value()) {
                Vector2 away = { s.dungeonPlayerPos.x - s.dungeonEngaged->pos.x,
                                 s.dungeonPlayerPos.y - s.dungeonEngaged->pos.y };
                float al = std::sqrt(away.x * away.x + away.y * away.y);
                if (al > 0.001f) {
                    float kb = 16.0f * (1.0f - s.playerHurtT / 0.30f);
                    px += away.x / al * kb; pz += away.y / al * kb;
                }
            }
        }
        T3CDrawHumanoid(g_t3cHumans[2].parts, px, pz, yaw, 1.0f,
                        shirt, Color{ 55, 60, 75, 255 },
                        Color{ 225, 200, 165, 255 }, a, false, pAtk, pCast);
    }
}

static Rectangle JournalHuntButtonRect(); // defined with the journal UI below
static bool Dung3DPointInUI(Vector2 m, const GameState& s) {
    if (CorpseUIPointIn(m)) return true; // corpse window / Loot button
    if (CheckCollisionPointRec(m, { 20, 56, 104, 40 })) return true; // in-dungeon MENU toggle
    if (s.dungeonMenuOpen && s.selectedDungeon.has_value() &&
        CheckCollisionPointRec(m, { 12, 104, 336, 328 })) return true; // MENU dropdown panel
    if (s.recallPickerOpen && CheckCollisionPointRec(m, RecallPickerRect())) return true; // recall modal
    if (CheckCollisionPointRec(m, { 452, 116, 68, 30 })) return true; // the 2D/3D toggle button
    if (CheckCollisionPointRec(m, { 528, 116, 96, 30 })) return true; // the camera mode button
    if (CheckCollisionPointRec(m, { 20, 110, 330, 60 })) return true; // HP strip
    if (g_touchSeen && CheckCollisionPointRec(m, TargetButtonRect())) return true; // TARGET button
    if (CheckCollisionPointRec(m, { 160, kViewport.y + kViewport.height - 160.0f, 330, 55 })) return true; // quick items
    if (CheckCollisionPointRec(m, { 160, kViewport.y + kViewport.height - 100.0f, 580, 100 })) return true; // spell hotbar
    if (CheckCollisionPointRec(m, JournalHuntButtonRect())) return true; // LOG button (always visible, incl. dungeons)
    if (s.journalOpen && CheckCollisionPointRec(m, JournalPanelRect())) return true; // journal panel
    return false;
}

static void DrawDungeon3DWorld(GameState& s, int screenW, int screenH, const std::string& prompt,
                               bool inRange, Vector2 nearestPos, const std::string& nearestLabel) {
    int di = *s.selectedDungeon; // caller guarantees a selected dungeon
    Vector2 mouse = GetMousePosition();

    // --- Camera input: follow mode (fixed Diablo-style angle) or free orbit ---
    // C key or the HUD camera button toggles; pinch zooms on touch. In follow
    // mode drags don't orbit; wheel/pinch zoom always works. The indoor clamp in
    // Dungeon3DGetCam still applies on top of the follow+lookahead target.
    if (IsKeyPressed(KEY_C)) g_t3dFollowMode = !g_t3dFollowMode;
    Town3DPinchZoom(kDung3DDistMin, kDung3DDistMax);
    // --- Orbit / zoom input (the shared orbit state; tighter dungeon limits).
    // No click-picking - interaction stays walk-up + E / tap, like the 2D view.
    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT) &&
        CheckCollisionPointRec(mouse, kViewport) && !Dung3DPointInUI(mouse, s)) {
        g_t3dOrbiting = true;
        g_t3dLastMouse = mouse;
        g_t3dDragDist = 0.0f;
    }
    if (g_t3dOrbiting && IsMouseButtonDown(MOUSE_BUTTON_LEFT)) {
        Vector2 d = { mouse.x - g_t3dLastMouse.x, mouse.y - g_t3dLastMouse.y };
        g_t3dLastMouse = mouse;
        g_t3dDragDist += fabsf(d.x) + fabsf(d.y);
        if (!g_t3dFollowMode) {
            g_t3dYaw -= d.x * 0.006f;
            g_t3dPitch = std::clamp(g_t3dPitch + d.y * 0.005f, kT3DPitchMin, kT3DPitchMax);
        }
    }
    if (IsMouseButtonReleased(MOUSE_BUTTON_LEFT) && g_t3dOrbiting) {
        // Tap-to-flag (2026-09-24): a tap that wasn't a drag picks a monster the
        // same way the 2D click does - flagging it for auto-approach.
        bool wasClick = g_t3dDragDist < 8.0f;
        g_t3dOrbiting = false;
        if (wasClick && CheckCollisionPointRec(mouse, kViewport) && !Dung3DPointInUI(mouse, s)) {
            Town3DCam pc = Dungeon3DGetCam(s, screenW, screenH);
            Dungeon3DPickFlag(s, pc, mouse);
        }
    }
    if (!IsMouseButtonDown(MOUSE_BUTTON_LEFT)) g_t3dOrbiting = false;
    float wheel = GetMouseWheelMove();
    if (wheel != 0.0f && CheckCollisionPointRec(mouse, kViewport) && !Dung3DPointInUI(mouse, s))
        g_t3dDist = std::clamp(g_t3dDist * (1.0f - wheel * 0.12f), kDung3DDistMin, kDung3DDistMax);

    // --- 3D scene ---
    Dungeon3DEnsureTorch();
    Dungeon3DEnsureGround(di);
    Dungeon3DBuildWalls(di);
    Dungeon3DBuildProps(di);
    Vector3 torchSpots[kDung3DMaxTorches];
    int torchCount = 0;
    Dungeon3DTorchSpots(di, torchSpots, &torchCount);
    Town3DCam c = Dungeon3DGetCam(s, screenW, screenH);
    T3DApplyShake(c); // combat camera kick (hit / hurt), zero when idle
    Camera3D cam3d = { c.pos, c.target, { 0, 1, 0 }, c.fovY, CAMERA_PERSPECTIVE };
    T3DUpdateDayNight(0.0f, true); // indoors / underground: always the noon palette
    BeginMode3D(cam3d);
    bool torchOn = g_dung3dTorch.ready;
    if (torchOn) {
        // Per-frame shader state: torch positions at flame height, count, time.
        // Ground + wall models carry the torch shader on their materials (set in
        // Dungeon3DEnsureGround/Dungeon3DBuildWalls); the rlEnableShader here is
        // for the immediate-mode primitives below (monsters, player, pet), which
        // render with whatever shader is currently bound.
        Vector3 tpos[kDung3DMaxTorches];
        for (int i = 0; i < torchCount; i++) tpos[i] = { torchSpots[i].x, 62.0f, torchSpots[i].z };
        SetShaderValueV(g_dung3dTorch.shader, g_dung3dTorch.torchPosLoc, tpos, SHADER_UNIFORM_VEC3, torchCount);
        SetShaderValue(g_dung3dTorch.shader, g_dung3dTorch.torchCountLoc, &torchCount, SHADER_UNIFORM_INT);
        float t = (float)GetTime();
        SetShaderValue(g_dung3dTorch.shader, g_dung3dTorch.timeLoc, &t, SHADER_UNIFORM_FLOAT);
        rlEnableShader(g_dung3dTorch.shader.id);
    }
    DrawModel(g_dung3dGround.model, { 900, 0, 900 }, 1.0f, WHITE);
    if (g_dung3dWalls.loaded) DrawModel(g_dung3dWalls.model, { 0, 0, 0 }, 1.0f, WHITE);
    Dungeon3DDrawProps(); // KayKit wall dressing, same torch lighting as the walls
    // Phase 3 creatures use the same torch shader as the dungeon geometry
    // (falling back to the default shader when torch lighting is off).
    T3CKitUseShader(torchOn ? g_dung3dTorch.shader : T3CKitDefaultShader());
    {
        bool engaged = s.dungeonEngaged.has_value();
        const DungeonDef& dungeon = kDungeons[di];
        bool bossUnlocked = s.dungeonXP[di] >= dungeon.bossUnlockXp;
        bool dyingHere = false;
        for (const auto& d : s.dyingMonsters)
            if (d.zone == 1 && d.dungeonIdx == di) { dyingHere = true; break; }
        for (int i = 0; i < kDungeonRegularSlots; i++) {
            // The engaged slot is drawn separately below at its live position -
            // same convention as the 2D view.
            if (engaged && !s.dungeonEngaged->isBoss && s.dungeonEngaged->monsterIdx == i) continue;
            // Empty slots (waiting to respawn) show nothing - except the slot whose
            // monster is mid-death-animation, which draws the fall below. Pack
            // attackers draw at their chase positions.
            const GameState::DyingMonster* dying = dyingHere ? FindDyingDungeonSlot(s, di, i, false) : nullptr;
            bool isDying = dying != nullptr;
            const GameState::ActiveDungeonMonster* extra = !isDying ? FindDungeonExtra(s, i, false) : nullptr;
            if (!isDying && !extra && s.dungeonSpawnRespawn[di][i] > 0.0f) continue;
            Vector2 mp = isDying ? dying->pos : (extra ? extra->pos : DungeonMonsterLivePos(di, i, s.worldTime));
            Vector2 f = WanderFacing(i, s.worldTime);
            float shrink = isDying ? std::max(0.05f, dying->timer / dying->duration) : 1.0f;
            bool humanLook = T3CDungeonMonsterLook(di, i).humanoid;
            Dungeon3DDrawMonster(di, i, kT3CTrackMonsterDungeon + i, mp.x, mp.y, atan2f(f.y, f.x),
                                 Dungeon3DMonsterColor(di, false), humanLook ? 1.0f : shrink, -1.0f, -1.0f,
                                 (isDying && humanLook) ? 1.0f - shrink : -1.0f);
        }
        if (!(engaged && s.dungeonEngaged->isBoss)) {
            const GameState::DyingMonster* bossDying = dyingHere ? FindDyingDungeonSlot(s, di, kDungeonBossSlot, true) : nullptr;
            if (!bossDying && s.dungeonSpawnRespawn[di][kDungeonBossSlot] > 0.0f) {
                // boss slot empty - nothing to draw
            } else {
                Vector2 bp = bossDying ? bossDying->pos : DungeonMonsterLivePos(di, kDungeonBossSlot, s.worldTime);
                Vector2 f = WanderFacing(kDungeonBossSlot, s.worldTime);
                Color bc = bossUnlocked ? Dungeon3DMonsterColor(di, true) : Color{ 110, 110, 120, 255 };
                float shrink = bossDying ? std::max(0.05f, bossDying->timer / bossDying->duration) : 1.0f;
                bool humanLook = T3CDungeonMonsterLook(di, kDungeonBossSlot).humanoid;
                Dungeon3DDrawMonster(di, kDungeonBossSlot, kT3CTrackMonsterDungeon + kDungeonBossSlot, bp.x, bp.y, atan2f(f.y, f.x),
                                     bc, (bossUnlocked ? 1.0f : 0.9f) * (humanLook ? 1.0f : shrink), -1.0f, -1.0f,
                                     (bossDying && humanLook) ? 1.0f - shrink : -1.0f);
            }
        }
        if (engaged) {
            const GameState::ActiveDungeonMonster& am = *s.dungeonEngaged;
            Vector2 toPlayer = { s.dungeonPlayerPos.x - am.pos.x, s.dungeonPlayerPos.y - am.pos.y };
            float len = std::sqrt(toPlayer.x * toPlayer.x + toPlayer.y * toPlayer.y);
            Vector2 facing = len > 0.001f ? Vector2{ toPlayer.x / len, toPlayer.y / len } : Vector2{ 0, 1 };
            int midx = am.isBoss ? kDungeonBossSlot : am.monsterIdx;
            Dungeon3DDrawMonster(di, midx, kT3CTrackMonsterDungeon + kDungeonBossSlot + 1, am.pos.x, am.pos.y,
                                 atan2f(facing.y, facing.x),
                                 Dungeon3DMonsterColor(di, am.isBoss), 1.0f,
                                 MonsterCombatPhase3D(am.monsterAttackT), am.monsterHurtT);
        }
    }
    Dungeon3DDrawPlayer(s);
    // Fallen monsters lie where they died (2026-09-26, UO corpses) - see Wild3DDrawCorpse.
    for (const GameState::WorldCorpse& c : s.worldCorpses) {
        if (c.zone != 1 || (c.dungeonIdx >= 0 && c.dungeonIdx != di)) continue;
        float sink = c.timer < 10.0f ? (1.0f - c.timer / 10.0f) * 26.0f : 0.0f;
        rlPushMatrix();
        rlTranslatef(0.0f, -sink, 0.0f);
        int track = kT3CTrackCorpse + c.id % 64;
        bool human = c.dungeonIdx >= 0 && c.monsterIdx >= 0 && T3CDungeonMonsterLook(c.dungeonIdx, c.monsterIdx).humanoid;
        if (human)
            Dungeon3DDrawMonster(c.dungeonIdx, c.monsterIdx, track, c.pos.x, c.pos.y, c.yaw,
                                 ColorBrightness(Dungeon3DMonsterColor(c.dungeonIdx, c.isBoss), -0.2f), c.isBoss ? 1.3f : 1.0f,
                                 -1.0f, -1.0f, 1.0f);
        else CorpseDrawMound(c);
        rlPopMatrix();
        CorpseDrawGlint(c);
    }
    if (ActivePet(s)) {
        Vector2 d = { s.dungeonPlayerPos.x - s.companionPos.x,
                      s.dungeonPlayerPos.y - s.companionPos.y };
        float face = (d.x * d.x + d.y * d.y > 1.0f) ? atan2f(d.y, d.x) : 0.0f;
        T3CQuadLook plook = T3CPetLook(ActivePet(s)->role);
        T3CAnim pa = T3CMakeAnim(kT3CTrackCompanion, s.companionPos.x, s.companionPos.y);
        T3CDrawQuad(g_t3cQuads[plook.specIdx].parts, s.companionPos.x, s.companionPos.y,
                    face, plook.scale, plook.coat, pa, 0.0f, false);
    }
    if (torchOn) rlEnableShader(rlGetShaderIdDefault());
    // --- Unlit dressing: torch poles + flames, exit portal, rings ---
    if (torchOn) {
        for (int i = 0; i < torchCount; i++) {
            DrawCylinder({ torchSpots[i].x, 25, torchSpots[i].z }, 4, 6, 50, 6, Color{ 40, 30, 22, 255 });
            float flick = 1.0f + 0.12f * sinf((float)GetTime() * 11.0f + (float)i * 2.3f);
            DrawBillboard(cam3d, g_dung3dTorch.flameTex, { torchSpots[i].x, 62.0f, torchSpots[i].z },
                          46.0f * flick, WHITE);
        }
    }
    {
        // Exit portal at the exact 2D exit position.
        float pulse = 0.6f + 0.25f * sinf((float)GetTime() * 3.0f);
        DrawCylinder({ kDung3DExitPos.x, 5, kDung3DExitPos.y }, 30, 30, 8, 20, Color{ 70, 190, 160, 255 });
        Town3DDrawGroundRing(kDung3DExitPos.x, kDung3DExitPos.y, 6.0f, 34.0f, 46.0f, 28,
                             Fade(Color{ 120, 255, 210, 255 }, pulse));
    }
    {
        float pulse = 0.60f + 0.18f * sinf((float)GetTime() * 4.0f);
        if (s.dungeonEngaged.has_value())
            Town3DDrawGroundRing(s.dungeonEngaged->pos.x, s.dungeonEngaged->pos.y, 3.0f, 46.0f, 56.0f, 36,
                                 Fade(Color{ 255, 80, 60, 255 }, pulse));
        else if (inRange)
            Town3DDrawGroundRing(nearestPos.x, nearestPos.y, 3.0f, 52.0f, 62.0f, 36,
                                 Fade(Color{ 255, 196, 110, 255 }, pulse));
    }
    // Combat FX (2026-09-24): flag marker, spell projectiles/impacts, heal +
    // vigor auras, summoned fiend - world-space, so they sit in the scene.
    DrawFlagMarker3D(s, 1);
    DrawSpellFX3D(s, 1);
    DrawHitSparks3D(1, cam3d);
    EndMode3D();

    // --- 2D overlay: labels (distance-faded), engaged HP bar, prompt ---
    {
        const float fadeNear = 500.0f, fadeFar = 1100.0f;
        auto label3D = [&](float x, float y, float z, const std::string& text) {
            Vector2 sp;
            if (!Town3DProject(c, { x, y, z }, &sp)) return;
            if (sp.x < -60 || sp.x > screenW + 60 || sp.y < 100 || sp.y > screenH) return;
            float bd = hypotf(c.pos.x - x, c.pos.z - z);
            float a = std::clamp((fadeFar - bd) / (fadeFar - fadeNear), 0.0f, 1.0f);
            if (a < 0.03f) return;
            int fsz = (int)(11.0f + 3.0f * a);
            int w = MeasureUIText(text.c_str(), fsz);
            int sx = (int)(sp.x - w / 2), sy = (int)(sp.y - fsz);
            DrawRectangle(sx - 4, sy - 2, w + 8, fsz + 5, Fade(BLACK, 0.55f * a));
            DrawUIText(text.c_str(), sx, sy, fsz, Fade(WHITE, a));
        };
        label3D(kDung3DExitPos.x, 80, kDung3DExitPos.y, "Exit");
        if (s.dungeonXP[di] >= kDungeons[di].bossUnlockXp) {
            Vector2 bp = DungeonMonsterLivePos(di, kDungeonBossSlot, s.worldTime);
            label3D(bp.x, 90, bp.y, kDungeons[di].boss.name + " (Boss)");
        }
        if (inRange && !s.dungeonEngaged.has_value() && !nearestLabel.empty())
            label3D(nearestPos.x, 80, nearestPos.y, nearestLabel);
    }
    if (s.dungeonEngaged.has_value()) {
        const GameState::ActiveDungeonMonster& am = *s.dungeonEngaged;
        Vector2 sp;
        if (Town3DProject(c, { am.pos.x, 60, am.pos.y }, &sp)) {
            float hpPct = std::clamp(am.hp / am.maxHp, 0.0f, 1.0f);
            DrawRectangle((int)sp.x - 30, (int)sp.y - 14, 60, 8, Fade(BLACK, 0.5f));
            DrawRectangle((int)sp.x - 30, (int)sp.y - 14, (int)(60 * hpPct), 8, Color{ 122, 46, 46, 255 });
        }
    }
    if (!prompt.empty()) {
        int w = MeasureUIText(prompt.c_str(), 14);
        int sx = (int)(screenW - w) / 2, sy = screenH - 96;
        DrawRectangle(sx - 6, sy - 3, w + 12, 22, Fade(BLACK, 0.55f));
        DrawUIText(prompt.c_str(), sx, sy, 14, WHITE);
    }
    DrawFloatTexts3D(s, c, 1, screenW, screenH); // combat feel: damage numbers / MISS
    DrawUIText(TextFormat("%s - 3D view: drag to orbit, wheel to zoom. [V] toggles 2D.",
                          kDungeons[di].name.c_str()),
               20, 196, 12, Color{ 200, 180, 150, 255 });
}


// ---------------------------------------------------------------------
// Building detail / upgrade panel - extracted 2026-09-24 from DrawTownScreen
// so building interiors can open the identical panel from their signature
// furniture (anvil, teller counter, ...). Content unchanged: craft buildings
// show upgrade info + "Craft here", amenities show their screen links.
// ---------------------------------------------------------------------
static void DrawBuildingDetailPanel(GameState& s, int screenW) {
    if (s.selectedTile.has_value()) {
        std::string key = *s.selectedTile;
        Rectangle panelBg = { 20, 500, (float)(screenW - 40), 220 };
        DrawRectangleRounded(panelBg, 0.06f, 8, Fade(kColorPageBg, 0.97f));
        DrawRectangleRoundedLines(panelBg, 0.06f, 8, Fade(BLACK, 0.4f));
        int panelY = (int)panelBg.y + 16;

        DrawUIText(TileNameFor(key).c_str(), 36, panelY, 18, kColorText);
        if (Button({ (float)(screenW - 80), (float)panelY - 4, 44, 26 }, "X", true)) s.selectedTile.reset();

        if (int idx = FindCraftBuildingIndex(key); idx >= 0) {
            const BuildingDef& def = kCraftBuildings[idx];
            int lvl = s.buildingLevel[idx];
            std::string capLine = "Skill cap: " + std::to_string(def.levels[lvl - 1].cap);
            DrawUIText(capLine.c_str(), 36, panelY + 28, 13, DARKGRAY);

            if (lvl < 5) {
                const BuildingLevel& next = def.levels[lvl];
                std::string resName = def.resource == Resource::Wood ? "wood"
                                      : def.resource == Resource::Ore ? "ore"
                                      : def.resource == Resource::Leather ? "leather" : "";
                std::string costLine = "Upgrade cost: " + std::to_string(next.goldCost) + "g" +
                    (def.resource != Resource::None ? (" + " + std::to_string(next.resourceCost) + " " + resName) : "") +
                    "  (" + std::to_string((int)next.upgradeTimeSec) + "s)";
                DrawUIText(costLine.c_str(), 36, panelY + 48, 13, DARKGRAY);

                bool upgrading = s.upgrading.has_value();
                if (Button({ 36, (float)(panelY + 72), 160, 34 }, "Upgrade", !upgrading))
                    TryStartUpgrade(s, key);
                if (upgrading && s.upgrading->buildingKey == key) {
                    float pct = 1.0f - (s.upgrading->secondsRemaining / next.upgradeTimeSec);
                    Rectangle bar = { 36, (float)(panelY + 112), 200, 8 };
                    DrawRectangleRec(bar, Fade(BLACK, 0.25f));
                    DrawRectangleRec({ bar.x, bar.y, bar.width * std::clamp(pct, 0.0f, 1.0f), bar.height }, kColorSlate);
                }
            } else {
                DrawUIText("Max level reached.", 36, panelY + 48, 13, DARKGRAY);
            }
            // Step inside and actually use the place, instead of tabbing away to Craft
            // by hand - jumps straight to this building's own recipe tab.
            if (Button({ 220, (float)(panelY + 72), 160, 34 }, "Craft here", true)) {
                s.craftBuildingTab = idx;
                s.screen = Screen::Craft;
                s.selectedTile.reset();
            }
        } else {
            DrawUIText("(No upgrades - amenity building.)", 36, panelY + 28, 13, DARKGRAY);
            // Same "step inside and use it" idea as the craft buildings above, for the
            // amenities that have an actual screen of their own.
            struct AmenityLink { const char* label; Screen target; };
            std::optional<AmenityLink> link;
            if (key == "bank" || key == "townhall") link = AmenityLink{ "Manage the Vaultkeep", Screen::Bank };
            else if (key == "stable") link = AmenityLink{ "Visit the Wildkeep", Screen::Pets };
            else if (key == "healer") link = AmenityLink{ "Rest & bandage up", Screen::Character };
            else if (key == "provisioner") link = AmenityLink{ "Browse the wares", Screen::Provisioner };
            else if (key == "furtrader") link = AmenityLink{ "Browse furs & cold-weather gear", Screen::FurTrader };
            else if (key == "minersguild") link = AmenityLink{ "Visit the Guild assay office", Screen::MinersGuild }; // Phase 4
            if (link) {
                if (Button({ 36, (float)(panelY + 56), 220, 34 }, link->label, true)) {
                    s.screen = link->target;
                    s.selectedTile.reset();
                }
            }
        }
        DrawUIText("Walk away or press [X] to close.", 36, (int)panelBg.y + 190, 13, Fade(DARKGRAY, 0.8f));
    }
}

// =====================================================================
// Building interiors (2026-09-24) - walkable rooms inside each of the ten
// town buildings. One Screen::Interior reuses the town's movement,
// interaction, 2D/3D rendering, and camera machinery: 2D is a top-down
// room that fills the viewport; 3D reuses Town3DGetCamFor with tighter
// zoom limits. Enter with E at a building's door in town; exit with E at
// the room's door. Signature furniture opens DrawBuildingDetailPanel -
// the same panel the old exterior E-press opened - so every existing
// link (Craft/Bank/Pets/Character/House/Provisioner) keeps working.
// =====================================================================

// 2026-09-25 bugfix, re-derived (the 2026-09-24 fix of 300-900 quietly
// regressed back to the pre-fix 150-520 at some point across drops, and
// re-testing found 300-900 itself no longer clears the problem either -
// interiors now force a steeper follow pitch, kT3DFollowPitch=0.96 rad,
// than whatever this range was originally tuned against): interiors use the
// same elevated-orbit camera math as Town/Wilderness, where most of the
// "distance" value becomes camera *height*, not proximity. A camera entering
// from Town/Wilderness carries over whatever distance it last had (often
// ~650, well inside the old 300-900 range), and at this pitch that's still
// close enough to fill the whole frame with the floor's flat color. Verified
// empirically (screenshots at 650/900/1200/1500/3000) that ~1200 is the
// first distance that reliably frames the whole room; kInt3DDistMin is set
// there so Town3DGetCamFor's entry clamp forces any incoming distance up to
// a safe minimum regardless of what screen the camera is coming from.
static const float kInt3DDistMin = 300.0f;        // 3D zoom limits for rooms (2026-09-26: close, cutaway view)
static const float kInt3DDistMax = 900.0f;
static const int kInteriorCamId = 3;            // Town3DGetCamFor id (0=town 1=wild 2=dungeon)

struct InteriorPropDef {
    const char* dir;    // assets/interiors/<dir>/ ("" = 2D shape only)
    const char* model;  // "Anvil.gltf" ("" = 2D shape only)
    const char* label;
    float x, y;         // room coords, prop center
    float rotDeg;       // 3D yaw
    float sc;           // 3D extra scale over kT3DModScale
    float yOff;         // 3D lift above the floor, world units (wall-hung items)
    float bw, bh;       // blocker AABB; 0/0 = walk-through decoration
    const char* action; // "exit" | "panel" | ""
    Color c2d;          // 2D shape color
    float sw, sh;       // 2D shape size
};

// ---- Room & house surfaces (2026-09-26) -------------------------------------------
// Procedural 256px tiling textures for floors, walls and roofs - shared by the
// shop interiors, the homestead interior and the homestead's outside. Made on
// first use; each is a small pixel program (planks with grain and seams,
// flagstones from a jittered cell pattern, timber framing, stone courses...).
// (enum IntSurface lives up with the housing constants - houses pick their styles from it)
static Texture2D g_isTex[kIsCount];
static bool g_isReady[kIsCount] = {};
static unsigned SurfHash(int x, int y, int k) {
    unsigned h = (unsigned)x * 374761393u + (unsigned)y * 668265263u + (unsigned)k * 2246822519u;
    h = (h ^ (h >> 13)) * 1274126177u;
    return h ^ (h >> 16);
}
static float SurfRand(int x, int y, int k) { return (SurfHash(x, y, k) & 0xFFFF) / 65535.0f; }
static Color SurfMul(Color c, float f) {
    return { (unsigned char)std::clamp(c.r * f, 0.0f, 255.0f), (unsigned char)std::clamp(c.g * f, 0.0f, 255.0f),
             (unsigned char)std::clamp(c.b * f, 0.0f, 255.0f), 255 };
}
static Color SurfPixel(int k, int x, int y) {
    const int N = 256;
    float n = SurfRand(x, y, k) - 0.5f; // fine grain
    auto planks = [&](Color base, int ph, float spread) -> Color { // horizontal planks, staggered joints
        int row = y / ph;
        float tone = 0.86f + 0.24f * SurfRand(row, 7, k);
        float grain = sinf(x * 0.07f + row * 3.1f + sinf(y * 0.45f + row) * 1.8f) * 0.07f;
        float f = tone + grain + n * spread;
        int yy = y % ph;
        if (yy == 0) f *= 0.45f; else if (yy == 1) f *= 0.8f;
        int joint = (int)(SurfRand(row, 3, k) * N);
        if (abs(((x - joint) % 128 + 128) % 128) < 1) f *= 0.55f;
        return SurfMul(base, f);
    };
    switch (k) {
        case kIsOak: return planks({ 150, 106, 64, 255 }, 32, 0.10f);
        case kIsDarkPlank: return planks({ 96, 64, 42, 255 }, 32, 0.10f);
        case kIsPlankWall: { // vertical planks
            int col = x / 32; float tone = 0.85f + 0.25f * SurfRand(col, 9, k);
            float f = tone + sinf(y * 0.06f + col * 2.3f + sinf(x * 0.5f) * 1.4f) * 0.06f + n * 0.1f;
            if (x % 32 == 0) f *= 0.45f;
            return SurfMul({ 128, 92, 58, 255 }, f);
        }
        case kIsFlagstone: case kIsSandstone: case kIsStoneWall: case kIsMarble: {
            bool courses = (k == kIsStoneWall || k == kIsSandstone || k == kIsMarble);
            float mortar = 1.0f, tone;
            if (courses) { // brick-like courses of blocks
                int ch = (k == kIsMarble) ? 128 : (k == kIsSandstone ? 42 : 32);
                int cw = (k == kIsMarble) ? 128 : (k == kIsSandstone ? 64 : 48);
                int row = y / ch; int off = (row % 2) * (cw / 2);
                int col = (x + off) / cw;
                int lx = (x + off) % cw, ly = y % ch;
                tone = 0.82f + 0.3f * SurfRand(col, row, k);
                if (lx < 2 || ly < 2) mortar = (k == kIsMarble) ? 0.85f : 0.55f;
            } else { // flagstones: nearest jittered cell point, grout on the borders
                int cs = 64; int gx = x / cs, gy = y / cs;
                float best = 1e9f, second = 1e9f; int bi = 0;
                for (int dy = -1; dy <= 1; dy++)
                    for (int dx = -1; dx <= 1; dx++) {
                        int cx = gx + dx, cy = gy + dy;
                        int wx = (cx + 4) % 4, wy = (cy + 4) % 4; // wraps on the 4x4 cell tile
                        float px = cx * cs + SurfRand(wx, wy, k + 1) * cs, py = cy * cs + SurfRand(wx, wy, k + 2) * cs;
                        float d = sqrtf((x - px) * (x - px) + (y - py) * (y - py));
                        if (d < best) { second = best; best = d; bi = wx + wy * 4; }
                        else if (d < second) second = d;
                    }
                tone = 0.8f + 0.3f * SurfRand(bi, 1, k);
                if (second - best < 3.0f) mortar = 0.5f;
            }
            Color base = k == kIsFlagstone ? Color{ 130, 124, 116, 255 } : k == kIsStoneWall ? Color{ 118, 112, 104, 255 }
                       : k == kIsSandstone ? Color{ 196, 172, 128, 255 } : Color{ 226, 222, 214, 255 };
            float f = tone * mortar + n * 0.12f;
            if (k == kIsMarble && fabsf(sinf(x * 0.021f + y * 0.033f + SurfRand(x / 16, y / 16, 5) * 2.5f)) < 0.04f) f *= 0.78f; // veins
            return SurfMul(base, f);
        }
        case kIsTile: { // terracotta / ochre checker
            int tx = x / 64, ty = y / 64; bool alt = (tx + ty) % 2;
            Color base = alt ? Color{ 178, 96, 64, 255 } : Color{ 196, 160, 104, 255 };
            float f = 0.9f + 0.15f * SurfRand(tx, ty, k) + n * 0.1f;
            if (x % 64 < 3 || y % 64 < 3) f = 0.45f;
            return SurfMul(base, f);
        }
        case kIsStraw: {
            float f = 0.8f + 0.25f * SurfRand(x / 3, (y + x / 2) / 12, k) + n * 0.2f;
            return SurfMul({ 186, 152, 86, 255 }, f);
        }
        case kIsCarpet: { // deep red weave with a gold diamond lattice
            int dx = abs((x % 64) - 32), dy = abs((y % 64) - 32);
            bool line = abs(dx + dy - 24) < 2;
            float f = 0.92f + ((x + y) % 4 == 0 ? 0.05f : 0.0f) + n * 0.06f;
            return line ? SurfMul({ 196, 150, 70, 255 }, f) : SurfMul({ 120, 26, 32, 255 }, f);
        }
        case kIsTimber: { // cream plaster in dark oak framing (v: floor at the bottom row)
            float v = 1.0f - y / (float)N;
            bool beam = (x % 128) < 12 || v < 0.07f || fabsf(v - 0.62f) < 0.035f || v > 0.95f;
            int bay = x / 128; float bx = (x % 128 - 12) / 116.0f;
            if (!beam && v > 0.07f && v < 0.6f && fabsf((v - 0.07f) / 0.53f - (bay % 2 ? bx : 1.0f - bx)) < 0.045f) beam = true; // brace
            if (beam) return SurfMul({ 76, 50, 32, 255 }, 0.9f + n * 0.2f + sinf(x * 0.3f) * 0.03f);
            return SurfMul({ 222, 206, 170, 255 }, 0.92f + n * 0.1f + SurfRand(x / 8, y / 8, k) * 0.06f);
        }
        case kIsWhitewash: { // lime-washed plaster over a blue-grey wainscot
            float v = 1.0f - y / (float)N;
            if (v < 0.3f) { float f = 0.9f + n * 0.12f; if (x % 32 == 0) f *= 0.7f; if (fabsf(v - 0.3f) < 0.02f) f *= 0.6f; return SurfMul({ 92, 110, 128, 255 }, f); }
            return SurfMul({ 232, 228, 216, 255 }, 0.94f + n * 0.08f + SurfRand(x / 16, y / 16, k) * 0.05f);
        }
        case kIsLogWall: { // stacked logs: round shading across each log, dark chinking
            int ly = y % 32; float t = (ly - 16) / 16.0f;
            float f = (0.7f + 0.35f * sqrtf(std::max(0.0f, 1.0f - t * t))) * (0.92f + 0.1f * SurfRand(y / 32, 4, k)) + n * 0.12f;
            if (ly < 2) f *= 0.4f;
            return SurfMul({ 130, 92, 58, 255 }, f);
        }
        case kIsThatch: { // straw layers with downward strands
            int band = y / 40; float f = 0.8f + 0.25f * SurfRand(x / 2, band, k) + n * 0.25f;
            if (y % 40 > 34) f *= 0.65f;
            return SurfMul({ 176, 140, 78, 255 }, f);
        }
        case kIsSlate: case kIsRedTile: case kIsShingle: { // overlapping rows
            int rh = k == kIsRedTile ? 28 : 24, rw = k == kIsRedTile ? 32 : 40;
            int row = y / rh, off = (row % 2) * rw / 2, col = (x + off) / rw;
            int lx = (x + off) % rw, ly = y % rh;
            float f = 0.85f + 0.25f * SurfRand(col, row, k) + n * 0.12f;
            if (ly > rh - 4) f *= 0.55f;           // shadow of the row above
            if (lx < 2) f *= 0.7f;
            if (k == kIsRedTile) f *= 0.8f + 0.25f * sinf(lx / (float)rw * 3.14159f); // round tiles
            Color base = k == kIsSlate ? Color{ 84, 90, 104, 255 } : k == kIsRedTile ? Color{ 170, 78, 54, 255 } : Color{ 120, 84, 54, 255 };
            return SurfMul(base, f);
        }
    }
    return MAGENTA;
}
static const Texture2D& SurfTex(int k) {
    k = std::clamp(k, 0, kIsCount - 1);
    if (!g_isReady[k]) {
        const int N = 256;
        Image img = GenImageColor(N, N, BLANK);
        Color* px = (Color*)img.data;
        for (int y = 0; y < N; y++) for (int x = 0; x < N; x++) px[y * N + x] = SurfPixel(k, x, y);
        g_isTex[k] = LoadTextureFromImage(img);
        UnloadImage(img);
        GenTextureMipmaps(&g_isTex[k]);
        SetTextureFilter(g_isTex[k], TEXTURE_FILTER_TRILINEAR);
        SetTextureWrap(g_isTex[k], TEXTURE_WRAP_REPEAT);
        g_isReady[k] = true;
    }
    return g_isTex[k];
}
static const char* SurfName(int k) {
    static const char* names[kIsCount] = { "Oak Planks", "Dark Planks", "Flagstone", "Terracotta Tile", "Straw", "Marble", "Red Carpet",
                                           "Timber & Plaster", "Fieldstone", "Log", "Plank", "Sandstone", "Whitewash",
                                           "Thatch", "Slate", "Red Tile", "Wood Shingle" };
    return names[std::clamp(k, 0, kIsCount - 1)];
}
// Textured quad (immediate mode, both sides). Corners in order around the quad.
static void SurfQuad(int k, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 ta, Vector2 tb, Vector2 tc, Vector2 td, Color tint) {
    rlSetTexture(SurfTex(k).id);
    rlBegin(RL_QUADS);
    rlColor4ub(tint.r, tint.g, tint.b, tint.a);
    rlTexCoord2f(ta.x, ta.y); rlVertex3f(a.x, a.y, a.z);
    rlTexCoord2f(tb.x, tb.y); rlVertex3f(b.x, b.y, b.z);
    rlTexCoord2f(tc.x, tc.y); rlVertex3f(c.x, c.y, c.z);
    rlTexCoord2f(td.x, td.y); rlVertex3f(d.x, d.y, d.z);
    rlEnd();
    rlSetTexture(0);
}
// A horizontal textured floor rectangle, UVs in world units / `tile`.
static void SurfFloor(int k, float x0, float z0, float x1, float z1, float y, float tile, Color tint) {
    SurfQuad(k, { x0, y, z0 }, { x0, y, z1 }, { x1, y, z1 }, { x1, y, z0 },
             { x0 / tile, z0 / tile }, { x0 / tile, z1 / tile }, { x1 / tile, z1 / tile }, { x1 / tile, z0 / tile }, tint);
}
// An axis-aligned wall slab from (ax,az) to (bx,bz), thickness t, from y0 to y1,
// textured along its length (u) and height (v, floor at the bottom).
static void SurfWall(int k, float ax, float az, float bx, float bz, float t, float y0, float y1, float wallH, Color tint, Color capTint) {
    bool alongX = fabsf(bx - ax) >= fabsf(bz - az);
    float h = t * 0.5f;
    float x0 = std::min(ax, bx), x1 = std::max(ax, bx), z0 = std::min(az, bz), z1 = std::max(az, bz);
    if (alongX) { z0 -= h; z1 += h; } else { x0 -= h; x1 += h; }
    float len = alongX ? (x1 - x0) : (z1 - z0);
    float u0 = (alongX ? x0 : z0) / 128.0f, u1 = u0 + len / 128.0f;
    float v0 = 1.0f - y0 / wallH, v1 = 1.0f - y1 / wallH;
    Color side = SurfMul(tint, 0.82f);
    if (alongX) {
        SurfQuad(k, { x0, y0, z1 }, { x1, y0, z1 }, { x1, y1, z1 }, { x0, y1, z1 }, { u0, v0 }, { u1, v0 }, { u1, v1 }, { u0, v1 }, tint);
        SurfQuad(k, { x0, y0, z0 }, { x1, y0, z0 }, { x1, y1, z0 }, { x0, y1, z0 }, { u0, v0 }, { u1, v0 }, { u1, v1 }, { u0, v1 }, SurfMul(tint, 0.9f));
        float tu = t / 128.0f;
        SurfQuad(k, { x0, y0, z0 }, { x0, y0, z1 }, { x0, y1, z1 }, { x0, y1, z0 }, { 0, v0 }, { tu, v0 }, { tu, v1 }, { 0, v1 }, side);
        SurfQuad(k, { x1, y0, z0 }, { x1, y0, z1 }, { x1, y1, z1 }, { x1, y1, z0 }, { 0, v0 }, { tu, v0 }, { tu, v1 }, { 0, v1 }, side);
    } else {
        SurfQuad(k, { x1, y0, z0 }, { x1, y0, z1 }, { x1, y1, z1 }, { x1, y1, z0 }, { u0, v0 }, { u1, v0 }, { u1, v1 }, { u0, v1 }, side);
        SurfQuad(k, { x0, y0, z0 }, { x0, y0, z1 }, { x0, y1, z1 }, { x0, y1, z0 }, { u0, v0 }, { u1, v0 }, { u1, v1 }, { u0, v1 }, SurfMul(side, 1.08f));
        float tu = t / 128.0f;
        SurfQuad(k, { x0, y0, z0 }, { x1, y0, z0 }, { x1, y1, z0 }, { x0, y1, z0 }, { 0, v0 }, { tu, v0 }, { tu, v1 }, { 0, v1 }, tint);
        SurfQuad(k, { x0, y0, z1 }, { x1, y0, z1 }, { x1, y1, z1 }, { x0, y1, z1 }, { 0, v0 }, { tu, v0 }, { tu, v1 }, { 0, v1 }, tint);
    }
    // top cap in dark oak
    rlBegin(RL_QUADS);
    rlColor4ub(capTint.r, capTint.g, capTint.b, 255);
    rlVertex3f(x0, y1, z0); rlVertex3f(x0, y1, z1); rlVertex3f(x1, y1, z1); rlVertex3f(x1, y1, z0);
    rlEnd();
}
// Soft radial glow (candles, torches, window light) - additive billboards/pools.
static Texture2D g_glowTex;
static bool g_glowReady = false;
static const Texture2D& GlowTex() {
    if (!g_glowReady) {
        Image img = GenImageGradientRadial(64, 64, 0.0f, WHITE, BLANK);
        g_glowTex = LoadTextureFromImage(img);
        UnloadImage(img);
        SetTextureFilter(g_glowTex, TEXTURE_FILTER_BILINEAR);
        g_glowReady = true;
    }
    return g_glowTex;
}
static void GlowPool(float x, float z, float y, float r, Color c) { // flat pool of light on a floor
    rlSetTexture(GlowTex().id);
    rlBegin(RL_QUADS);
    rlColor4ub(c.r, c.g, c.b, c.a);
    rlTexCoord2f(0, 0); rlVertex3f(x - r, y, z - r);
    rlTexCoord2f(0, 1); rlVertex3f(x - r, y, z + r);
    rlTexCoord2f(1, 1); rlVertex3f(x + r, y, z + r);
    rlTexCoord2f(1, 0); rlVertex3f(x + r, y, z - r);
    rlEnd();
    rlSetTexture(0);
}

// ---- Homestead exterior 3D (Housing 2.0, 2026-09-26) -------------------------------
// The house outline (every non-empty cell) becomes a lit, textured shell: walls
// along the outside edges in the chosen wall style, window openings with glass
// on 'N' cells (warm and glowing at night), a plank door with a lantern on the
// door cell, timber corner posts, a stone plinth, a chimney, a sign post - and
// a hipped roof over the lot: the roof height at any point is its L-infinity
// distance to open ground, which gives clean hips over rectangles and proper
// valleys over L and T shapes. Rebuilt only when the plan or a style changes.
struct HxMesh { std::vector<float> p, n, t; std::vector<unsigned char> c; };
static void HxTri(HxMesh& m, Vector3 a, Vector3 b, Vector3 c, Vector2 ta, Vector2 tb, Vector2 tc, Color col, Vector3 want) {
    Vector3 u = { b.x - a.x, b.y - a.y, b.z - a.z }, v = { c.x - a.x, c.y - a.y, c.z - a.z };
    Vector3 nn = { u.y * v.z - u.z * v.y, u.z * v.x - u.x * v.z, u.x * v.y - u.y * v.x };
    float l = sqrtf(nn.x * nn.x + nn.y * nn.y + nn.z * nn.z);
    if (l < 1e-6f) return;
    nn = { nn.x / l, nn.y / l, nn.z / l };
    if (nn.x * want.x + nn.y * want.y + nn.z * want.z < 0.0f) { // keep the face turned the way it should light
        std::swap(b, c); std::swap(tb, tc);
        nn = { -nn.x, -nn.y, -nn.z };
    }
    const Vector3 P[3] = { a, b, c };
    const Vector2 T[3] = { ta, tb, tc };
    for (int i = 0; i < 3; i++) {
        m.p.insert(m.p.end(), { P[i].x, P[i].y, P[i].z });
        m.n.insert(m.n.end(), { nn.x, nn.y, nn.z });
        m.t.insert(m.t.end(), { T[i].x, T[i].y });
        m.c.insert(m.c.end(), { col.r, col.g, col.b, col.a });
    }
}
static void HxQuad(HxMesh& m, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 ta, Vector2 tb, Vector2 tc, Vector2 td,
                   Color col, Vector3 want) {
    HxTri(m, a, b, c, ta, tb, tc, col, want);
    HxTri(m, a, c, d, ta, tc, td, col, want);
}
static void HxBox(HxMesh& m, float x0, float y0, float z0, float x1, float y1, float z1, Color col) {
    const Vector2 o = { 0, 0 };
    HxQuad(m, { x0, y1, z0 }, { x1, y1, z0 }, { x1, y1, z1 }, { x0, y1, z1 }, o, o, o, o, col, { 0, 1, 0 });
    HxQuad(m, { x0, y0, z1 }, { x1, y0, z1 }, { x1, y1, z1 }, { x0, y1, z1 }, o, o, o, o, col, { 0, 0, 1 });
    HxQuad(m, { x0, y0, z0 }, { x1, y0, z0 }, { x1, y1, z0 }, { x0, y1, z0 }, o, o, o, o, SurfMul(col, 0.95f), { 0, 0, -1 });
    HxQuad(m, { x0, y0, z0 }, { x0, y0, z1 }, { x0, y1, z1 }, { x0, y1, z0 }, o, o, o, o, SurfMul(col, 0.97f), { -1, 0, 0 });
    HxQuad(m, { x1, y0, z0 }, { x1, y0, z1 }, { x1, y1, z1 }, { x1, y1, z0 }, o, o, o, o, col, { 1, 0, 0 });
}
static Mesh HxUpload(const HxMesh& m) {
    Mesh mesh = { 0 };
    int n = (int)(m.p.size() / 3);
    if (n <= 0) return mesh;
    mesh.vertexCount = n;
    mesh.triangleCount = n / 3;
    mesh.vertices = (float*)RL_MALLOC(sizeof(float) * 3 * n);
    mesh.normals = (float*)RL_MALLOC(sizeof(float) * 3 * n);
    mesh.texcoords = (float*)RL_MALLOC(sizeof(float) * 2 * n);
    mesh.colors = (unsigned char*)RL_MALLOC(4 * n);
    memcpy(mesh.vertices, m.p.data(), sizeof(float) * 3 * n);
    memcpy(mesh.normals, m.n.data(), sizeof(float) * 3 * n);
    memcpy(mesh.texcoords, m.t.data(), sizeof(float) * 2 * n);
    memcpy(mesh.colors, m.c.data(), 4 * n);
    UploadMesh(&mesh, false);
    return mesh;
}

enum HxPart { kHxWalls = 0, kHxRoof, kHxTrim, kHxDoor, kHxStone, kHxPartCount };
struct HxGlass { Vector3 a, b, c, d; Vector3 n; };
struct HouseExterior {
    std::string key;
    Mesh mesh[kHxPartCount] = {};
    Material mat[kHxPartCount] = {};
    bool matReady = false;
    std::vector<HxGlass> glass;       // window panes (drawn unlit: dark by day, lamplit at night)
    Vector3 lantern = { 0, 0, 0 };    // door lantern flame
    Vector3 sign = { 0, 0, 0 };       // sign board (name label rides above it)
    Vector3 smoke = { 0, 0, 0 };      // chimney top
    bool built = false;
};
static HouseExterior g_houseExt;

static void HouseExteriorBuild(const GameState& s) {
    const HousePlot& hp = kHousePlots[s.housePlotIdx];
    const int n = hp.cells;
    const std::string& L = s.houseLayout;
    std::string key = std::to_string(s.housePlotIdx) + L + char('0' + s.houseWallStyle) + char('0' + s.houseFloorStyle) + char('0' + s.houseRoofStyle);
    if (g_houseExt.built && g_houseExt.key == key) return;
    for (int i = 0; i < kHxPartCount; i++)
        if (g_houseExt.mesh[i].vertexCount > 0) { UnloadMesh(g_houseExt.mesh[i]); g_houseExt.mesh[i] = Mesh{ 0 }; }
    if (!g_houseExt.matReady) {
        Town3DEnsureLit();
        for (int i = 0; i < kHxPartCount; i++) {
            g_houseExt.mat[i] = LoadMaterialDefault();
            if (g_t3dLit.ready) g_houseExt.mat[i].shader = g_t3dLit.shader;
        }
        g_houseExt.matReady = true;
    }
    g_houseExt.mat[kHxWalls].maps[MATERIAL_MAP_DIFFUSE].texture = SurfTex(kHouseWallSurfs[s.houseWallStyle]);
    g_houseExt.mat[kHxRoof].maps[MATERIAL_MAP_DIFFUSE].texture = SurfTex(kHouseRoofSurfs[s.houseRoofStyle]);
    g_houseExt.mat[kHxDoor].maps[MATERIAL_MAP_DIFFUSE].texture = SurfTex(kIsDarkPlank);
    g_houseExt.mat[kHxStone].maps[MATERIAL_MAP_DIFFUSE].texture = SurfTex(kIsFlagstone);
    g_houseExt.key = key;
    g_houseExt.built = true;
    g_houseExt.glass.clear();
    g_houseSignPos = { 0, -1, 0 };

    const float S = kHouseCellSize, WH = 58.0f, ox = hp.pos.x - n * S * 0.5f, oz = hp.pos.y - n * S * 0.5f;
    auto foot = [&](int cx, int cy) { return HouseCellAt(L, n, cx, cy) != '.'; }; // off-plot reads '.'
    HxMesh walls, roof, trim, door, stone;
    const Color beam = { 74, 50, 32, 255 }, white = WHITE;
    const float wallU = 64.0f; // world units per wall texture repeat (outside scale)
    const float hasDoorOnly = L.find('D') != std::string::npos;
    bool doorDone = false;
    const int dx4[4] = { 0, 0, -1, 1 }, dy4[4] = { -1, 1, 0, 0 }; // N S W E

    // --- walls, windows, the door ---
    for (int cy = 0; cy < n; cy++)
        for (int cx = 0; cx < n; cx++) {
            if (!foot(cx, cy)) continue;
            char c = HouseCellAt(L, n, cx, cy);
            for (int k = 0; k < 4; k++) {
                if (foot(cx + dx4[k], cy + dy4[k])) continue;
                // edge endpoints (a -> b) and outward normal
                float x0 = ox + cx * S, z0 = oz + cy * S, x1 = x0 + S, z1 = z0 + S;
                Vector3 nrm = { (float)dx4[k], 0, (float)dy4[k] };
                Vector3 a, b;
                if (k == 0) { a = { x0, 0, z0 }; b = { x1, 0, z0 }; }
                else if (k == 1) { a = { x0, 0, z1 }; b = { x1, 0, z1 }; }
                else if (k == 2) { a = { x0, 0, z0 }; b = { x0, 0, z1 }; }
                else { a = { x1, 0, z0 }; b = { x1, 0, z1 }; }
                auto P = [&](float t, float y, float out) {
                    return Vector3{ a.x + (b.x - a.x) * t + nrm.x * out, y, a.z + (b.z - a.z) * t + nrm.z * out };
                };
                float u0 = (k < 2 ? a.x : a.z) / wallU, u1 = u0 + S / wallU;
                auto face = [&](float t0, float t1, float y0, float y1) { // a piece of the outer face
                    HxQuad(walls, P(t0, y0, 0), P(t1, y0, 0), P(t1, y1, 0), P(t0, y1, 0),
                           { u0 + (u1 - u0) * t0, 1.0f - y0 / WH }, { u0 + (u1 - u0) * t1, 1.0f - y0 / WH },
                           { u0 + (u1 - u0) * t1, 1.0f - y1 / WH }, { u0 + (u1 - u0) * t0, 1.0f - y1 / WH }, white, nrm);
                };
                auto reveal = [&](float t0, float t1, float y0, float y1, float depth) { // opening's inner sides
                    Vector2 o = { 0, 0 };
                    HxQuad(trim, P(t0, y0, 0), P(t0, y0, -depth), P(t0, y1, -depth), P(t0, y1, 0), o, o, o, o, Color{ 60, 44, 30, 255 },
                           { (b.x - a.x) / S, 0, (b.z - a.z) / S });
                    HxQuad(trim, P(t1, y0, 0), P(t1, y0, -depth), P(t1, y1, -depth), P(t1, y1, 0), o, o, o, o, Color{ 60, 44, 30, 255 },
                           { -(b.x - a.x) / S, 0, -(b.z - a.z) / S });
                    HxQuad(trim, P(t0, y1, 0), P(t1, y1, 0), P(t1, y1, -depth), P(t0, y1, -depth), o, o, o, o, Color{ 50, 36, 24, 255 }, { 0, -1, 0 });
                    HxQuad(trim, P(t0, y0, 0), P(t1, y0, 0), P(t1, y0, -depth), P(t0, y0, -depth), o, o, o, o, Color{ 90, 70, 50, 255 }, { 0, 1, 0 });
                };
                bool isDoor = c == 'D' && !doorDone;
                if (isDoor) {
                    doorDone = true;
                    const float t0 = 0.24f, t1 = 0.76f, dh = 44.0f;
                    face(0, t0, 0, WH); face(t1, 1, 0, WH); face(t0, t1, dh, WH);
                    reveal(t0, t1, 0, dh, 4.0f);
                    // plank door leaf, recessed, with a frame and iron studs
                    HxQuad(door, P(t0, 0, -4), P(t1, 0, -4), P(t1, dh, -4), P(t0, dh, -4), { 0, 1 }, { 0.6f, 1 }, { 0.6f, 0 }, { 0, 0 }, white, nrm);
                    Vector3 f0 = P(t0 - 0.03f, 0, 0.5f), f1 = P(t1 + 0.03f, dh + 4, 2.0f);
                    Vector3 lo = { std::min(f0.x, f1.x), 0, std::min(f0.z, f1.z) }, hi = { std::max(f0.x, f1.x), dh + 5, std::max(f0.z, f1.z) };
                    HxBox(trim, lo.x, dh, lo.z, hi.x, dh + 5, hi.z, beam); // lintel
                    Vector3 k0 = P(t0 - 0.02f, 0, 1.2f), k1 = P(t1 + 0.02f, 0, 1.2f);
                    HxBox(trim, k0.x - 2, 0, k0.z - 2, k0.x + 2, dh, k0.z + 2, beam);
                    HxBox(trim, k1.x - 2, 0, k1.z - 2, k1.x + 2, dh, k1.z + 2, beam);
                    Vector3 knob = P(0.66f, 22, -3.0f);
                    HxBox(trim, knob.x - 1.2f, 21, knob.z - 1.2f, knob.x + 1.2f, 23.5f, knob.z + 1.2f, Color{ 40, 36, 34, 255 });
                    // step, lantern bracket, sign post
                    Vector3 s0 = P(0.18f, 0, 0), s1 = P(0.82f, 0, 9.0f);
                    HxBox(stone, std::min(s0.x, s1.x), 0, std::min(s0.z, s1.z), std::max(s0.x, s1.x), 3.0f, std::max(s0.z, s1.z), white);
                    Vector3 lb = P(0.9f, 40, 3.0f);
                    HxBox(trim, lb.x - 1.5f, 38, lb.z - 1.5f, lb.x + 1.5f, 42, lb.z + 1.5f, Color{ 40, 36, 34, 255 });
                    g_houseExt.lantern = P(0.9f, 36, 5.0f);
                    HxBox(trim, g_houseExt.lantern.x - 2.5f, 31, g_houseExt.lantern.z - 2.5f, g_houseExt.lantern.x + 2.5f, 39, g_houseExt.lantern.z + 2.5f,
                          Color{ 50, 44, 38, 255 });
                    Vector3 sp = P(-0.25f, 0, 30.0f);
                    HxBox(trim, sp.x - 2, 0, sp.z - 2, sp.x + 2, 50, sp.z + 2, beam);
                    Vector3 arm = P(-0.25f, 0, 30.0f), armEnd = P(0.05f, 0, 30.0f);
                    HxBox(trim, std::min(arm.x, armEnd.x) - 1.5f, 46, std::min(arm.z, armEnd.z) - 1.5f,
                          std::max(arm.x, armEnd.x) + 1.5f, 49, std::max(arm.z, armEnd.z) + 1.5f, beam);
                    Vector3 bc = P(-0.1f, 0, 30.0f);
                    bool alongX = k < 2;
                    float bw2 = 11.0f, bt = 1.2f;
                    HxBox(trim, bc.x - (alongX ? bw2 : bt), 30, bc.z - (alongX ? bt : bw2), bc.x + (alongX ? bw2 : bt), 44, bc.z + (alongX ? bt : bw2),
                          Color{ 150, 108, 64, 255 });
                    g_houseExt.sign = { bc.x, 44, bc.z };
                    g_houseSignPos = g_houseExt.sign;
                } else if (c == 'N') {
                    const float t0 = 0.3f, t1 = 0.7f, y0 = 22.0f, y1 = 44.0f;
                    face(0, t0, 0, WH); face(t1, 1, 0, WH); face(t0, t1, 0, y0); face(t0, t1, y1, WH);
                    reveal(t0, t1, y0, y1, 3.0f);
                    g_houseExt.glass.push_back({ P(t0, y0, -3), P(t1, y0, -3), P(t1, y1, -3), P(t0, y1, -3), nrm });
                    // frame, mullions, sill, and shutters folded back on the wall
                    Vector3 m0 = P(0.5f, 0, -2.0f);
                    bool alongX = k < 2;
                    HxBox(trim, m0.x - (alongX ? 0.8f : 1.0f), y0, m0.z - (alongX ? 1.0f : 0.8f), m0.x + (alongX ? 0.8f : 1.0f), y1, m0.z + (alongX ? 1.0f : 0.8f), beam);
                    Vector3 h0 = P(t0, 0, -2.0f), h1 = P(t1, 0, -1.0f);
                    HxBox(trim, std::min(h0.x, h1.x), 32.5f, std::min(h0.z, h1.z), std::max(h0.x, h1.x), 34.0f, std::max(h0.z, h1.z), beam);
                    Vector3 sl0 = P(t0 - 0.05f, 0, 0), sl1 = P(t1 + 0.05f, 0, 4.0f);
                    HxBox(trim, std::min(sl0.x, sl1.x), y0 - 2.5f, std::min(sl0.z, sl1.z), std::max(sl0.x, sl1.x), y0, std::max(sl0.z, sl1.z), beam);
                    for (int side = 0; side < 2; side++) {
                        float ta = side == 0 ? t0 - 0.2f : t1, tb = side == 0 ? t0 : t1 + 0.2f;
                        Vector3 q0 = P(ta, 0, 0.6f), q1 = P(tb, 0, 1.6f);
                        HxBox(trim, std::min(q0.x, q1.x), y0 - 1, std::min(q0.z, q1.z), std::max(q0.x, q1.x), y1 + 1, std::max(q0.z, q1.z),
                              Color{ 70, 96, 70, 255 });
                    }
                } else {
                    face(0, 1, 0, WH);
                }
                // stone plinth along the base and a beam along the top
                Vector3 pb0 = P(0, 0, 0), pb1 = P(1, 0, 3.0f);
                HxBox(stone, std::min(pb0.x, pb1.x), 0, std::min(pb0.z, pb1.z), std::max(pb0.x, pb1.x), 6.0f, std::max(pb0.z, pb1.z), white);
                Vector3 tb0 = P(0, 0, 0), tb1 = P(1, 0, 2.0f);
                HxBox(trim, std::min(tb0.x, tb1.x), WH - 5, std::min(tb0.z, tb1.z), std::max(tb0.x, tb1.x), WH, std::max(tb0.z, tb1.z), beam);
            }
        }
    (void)hasDoorOnly;
    // corner posts where the outline turns
    for (int vy = 0; vy <= n; vy++)
        for (int vx = 0; vx <= n; vx++) {
            int cnt = foot(vx - 1, vy - 1) + foot(vx, vy - 1) + foot(vx - 1, vy) + foot(vx, vy);
            bool diag = cnt == 2 && foot(vx - 1, vy - 1) == foot(vx, vy);
            if (cnt == 0 || cnt == 4 || (cnt == 2 && !diag)) continue;
            float x = ox + vx * S, z = oz + vy * S;
            HxBox(trim, x - 3.5f, 0, z - 3.5f, x + 3.5f, WH, z + 3.5f, beam);
        }

    // --- hipped roof (half-cell heightfield) ---
    const int R = 2 * n;
    std::vector<float> dist((size_t)(R + 1) * (R + 1), 0.0f);
    float dmax = 0.0f;
    for (int j = 0; j <= R; j++)
        for (int i = 0; i <= R; i++) {
            float u = i * 0.5f, v = j * 0.5f, best = 1e9f;
            for (int b = -1; b <= n; b++)
                for (int a = -1; a <= n; a++) {
                    if (foot(a, b)) continue;
                    float ddx = std::max({ a - u, 0.0f, u - (a + 1) }), ddy = std::max({ b - v, 0.0f, v - (b + 1) });
                    best = std::min(best, std::max(ddx, ddy));
                }
            dist[(size_t)j * (R + 1) + i] = best;
            dmax = std::max(dmax, best);
        }
    const float pitch = std::min(0.95f, 96.0f / std::max(1.0f, dmax * S)), eave = WH - 2.0f, over = 5.0f;
    const float slopeK = sqrtf(1.0f + pitch * pitch) / std::max(0.05f, pitch);
    auto H = [&](int i, int j) { return eave + dist[(size_t)j * (R + 1) + i] * S * pitch; };
    // vertices on the eave are pushed out a little (the overhang) and dropped to match the slope
    auto V = [&](int i, int j) {
        float x = ox + i * S * 0.5f, z = oz + j * S * 0.5f, h = H(i, j);
        if (dist[(size_t)j * (R + 1) + i] <= 0.0f) {
            float px = 0, pz = 0;
            for (int b = -1; b <= 0; b++)
                for (int a = -1; a <= 0; a++) {
                    int cx = (int)floorf(i * 0.5f + a * 0.5f + 0.01f), cy = (int)floorf(j * 0.5f + b * 0.5f + 0.01f);
                    if (!foot(cx, cy)) { px += a * 2 + 1; pz += b * 2 + 1; }
                }
            float l = sqrtf(px * px + pz * pz);
            if (l > 0.01f) { x += px / l * over * 1.4f; z += pz / l * over * 1.4f; h -= over * pitch; }
        }
        return Vector3{ x, h, z };
    };
    const float rt = 60.0f; // world units per roof texture repeat
    for (int j = 0; j < R; j++)
        for (int i = 0; i < R; i++) {
            if (!foot(i / 2, j / 2)) continue;
            Vector3 p00 = V(i, j), p10 = V(i + 1, j), p01 = V(i, j + 1), p11 = V(i + 1, j + 1);
            float h00 = H(i, j), h10 = H(i + 1, j), h01 = H(i, j + 1), h11 = H(i + 1, j + 1);
            bool diagA = fabsf(h00 - h11) >= fabsf(h10 - h01); // split along the hip / valley line
            auto tri = [&](Vector3 a, Vector3 b, Vector3 c, float ha, float hb, float hc) {
                // uv: along the contour (u) and up the slope (v), so rows run parallel to the eaves
                Vector3 e1 = { b.x - a.x, hb - ha, b.z - a.z }, e2 = { c.x - a.x, hc - ha, c.z - a.z };
                Vector3 nn = { e1.y * e2.z - e1.z * e2.y, e1.z * e2.x - e1.x * e2.z, e1.x * e2.y - e1.y * e2.x };
                if (nn.y < 0) nn = { -nn.x, -nn.y, -nn.z };
                bool ew = fabsf(nn.x) > fabsf(nn.z);
                bool flat = fabsf(nn.x) + fabsf(nn.z) < 0.02f * fabsf(nn.y);
                auto uv = [&](Vector3 p, float h) {
                    if (flat) return Vector2{ p.x / rt, p.z / rt };
                    return Vector2{ (ew ? p.z : p.x) / rt, -(h - eave) * slopeK / rt };
                };
                HxTri(roof, a, b, c, uv(a, ha), uv(b, hb), uv(c, hc), WHITE, { 0, 1, 0 });
            };
            if (diagA) { tri(p00, p10, p11, h00, h10, h11); tri(p00, p11, p01, h00, h11, h01); }
            else { tri(p00, p10, p01, h00, h10, h01); tri(p10, p11, p01, h10, h11, h01); }
        }
    // soffit: close the gap between the overhang and the wall top
    for (int cy = 0; cy < n; cy++)
        for (int cx = 0; cx < n; cx++) {
            if (!foot(cx, cy)) continue;
            for (int k = 0; k < 4; k++) {
                if (foot(cx + dx4[k], cy + dy4[k])) continue;
                float x0 = ox + cx * S, z0 = oz + cy * S, x1 = x0 + S, z1 = z0 + S;
                Vector3 a, b, o = { dx4[k] * over * 1.4f, 0, dy4[k] * over * 1.4f };
                if (k == 0) { a = { x0, eave, z0 }; b = { x1, eave, z0 }; }
                else if (k == 1) { a = { x0, eave, z1 }; b = { x1, eave, z1 }; }
                else if (k == 2) { a = { x0, eave, z0 }; b = { x0, eave, z1 }; }
                else { a = { x1, eave, z0 }; b = { x1, eave, z1 }; }
                Vector2 zz = { 0, 0 };
                float dy = over * pitch;
                HxQuad(trim, a, b, { b.x + o.x, eave - dy, b.z + o.z }, { a.x + o.x, eave - dy, a.z + o.z }, zz, zz, zz, zz,
                       Color{ 64, 46, 30, 255 }, { 0, -1, 0 });
            }
        }
    // chimney on the house cell furthest from the door
    {
        Vector2 dpos = HouseDoorPos(hp, L);
        int bx = -1, by = -1; float bd = -1;
        for (int cy = 0; cy < n; cy++)
            for (int cx = 0; cx < n; cx++) {
                if (!foot(cx, cy)) continue;
                Vector2 cc = HouseCellCenter(hp, cx, cy);
                float d = Dist(cc, dpos) + (dist[(size_t)(2 * cy + 1) * (R + 1) + 2 * cx + 1] > 0.9f ? 0 : -40.0f);
                if (d > bd) { bd = d; bx = cx; by = cy; }
            }
        if (bx >= 0) {
            float x = ox + bx * S + S * 0.5f, z = oz + by * S + S * 0.5f;
            float top = H(2 * bx + 1, 2 * by + 1) + 24.0f;
            HxBox(stone, x - 7, eave, z - 7, x + 7, top, z + 7, Color{ 150, 140, 130, 255 });
            HxBox(trim, x - 8.5f, top - 3, z - 8.5f, x + 8.5f, top, z + 8.5f, Color{ 90, 84, 80, 255 });
            g_houseExt.smoke = { x, top, z };
        }
    }
    g_houseExt.mesh[kHxWalls] = HxUpload(walls);
    g_houseExt.mesh[kHxRoof] = HxUpload(roof);
    g_houseExt.mesh[kHxTrim] = HxUpload(trim);
    g_houseExt.mesh[kHxDoor] = HxUpload(door);
    g_houseExt.mesh[kHxStone] = HxUpload(stone);
}

static void Wild3DDrawHouse(GameState& s, bool shadowPass) {
    if (s.housePlotIdx < 0 || s.housePlotIdx >= (int)kHousePlots.size()) return;
    const HousePlot& hp = kHousePlots[s.housePlotIdx];
    if (!HouseLayoutValid(s.houseLayout, hp.cells) || s.houseLayout.find_first_not_of('.') == std::string::npos) return;
    HouseExteriorBuild(s);
    T3DLiftScope lift(hp.pos.x, hp.pos.y);
    rlDisableBackfaceCulling();
    for (int i = 0; i < kHxPartCount; i++)
        if (g_houseExt.mesh[i].vertexCount > 0) DrawMesh(g_houseExt.mesh[i], g_houseExt.mat[i], MatrixIdentity());
    rlEnableBackfaceCulling();
    if (shadowPass) return;
    // glass: sky-dark by day, lamplit from within at night; a door lantern and chimney smoke
    float night = g_t3dNight, t = (float)GetTime();
    Color day = { 58, 74, 92, 255 }, lit = { 255, 196, 118, 255 };
    Color g = ColorLerp(day, lit, std::clamp(night * 1.3f, 0.0f, 1.0f));
    rlBegin(RL_QUADS);
    for (const HxGlass& w : g_houseExt.glass) {
        rlColor4ub(g.r, g.g, g.b, 255);
        rlVertex3f(w.a.x, w.a.y, w.a.z); rlVertex3f(w.b.x, w.b.y, w.b.z); rlVertex3f(w.c.x, w.c.y, w.c.z); rlVertex3f(w.d.x, w.d.y, w.d.z);
    }
    rlEnd();
    BeginBlendMode(BLEND_ADDITIVE);
    rlDisableDepthMask();
    if (night > 0.15f) {
        float k = std::clamp((night - 0.15f) * 1.6f, 0.0f, 1.0f);
        for (const HxGlass& w : g_houseExt.glass) { // warm spill on the ground under each window
            Vector3 c = { (w.a.x + w.c.x) * 0.5f + w.n.x * 22, 0.8f, (w.a.z + w.c.z) * 0.5f + w.n.z * 22 };
            GlowPool(c.x, c.z, c.y, 30.0f, Color{ (unsigned char)(200 * k), (unsigned char)(140 * k), (unsigned char)(70 * k), 255 });
        }
        float fl = 0.85f + 0.15f * sinf(t * 9.0f) * sinf(t * 3.7f);
        Vector3 L = g_houseExt.lantern;
        GlowPool(L.x, L.z, 0.8f, 42.0f * fl, Color{ (unsigned char)(230 * k), (unsigned char)(150 * k), (unsigned char)(70 * k), 255 });
        Camera3D cam = { 0 };
        (void)cam;
        rlSetTexture(GlowTex().id);
        rlBegin(RL_QUADS);
        float r = 9.0f * fl;
        rlColor4ub((unsigned char)(255 * k), (unsigned char)(190 * k), (unsigned char)(100 * k), 255);
        rlTexCoord2f(0, 0); rlVertex3f(L.x - r, L.y - r, L.z); rlTexCoord2f(1, 0); rlVertex3f(L.x + r, L.y - r, L.z);
        rlTexCoord2f(1, 1); rlVertex3f(L.x + r, L.y + r, L.z); rlTexCoord2f(0, 1); rlVertex3f(L.x - r, L.y + r, L.z);
        rlTexCoord2f(0, 0); rlVertex3f(L.x, L.y - r, L.z - r); rlTexCoord2f(1, 0); rlVertex3f(L.x, L.y - r, L.z + r);
        rlTexCoord2f(1, 1); rlVertex3f(L.x, L.y + r, L.z + r); rlTexCoord2f(0, 1); rlVertex3f(L.x, L.y + r, L.z - r);
        rlEnd();
        rlSetTexture(0);
    }
    EndBlendMode();
    // chimney smoke: a few soft grey puffs drifting up and away
    if (g_houseExt.smoke.y > 0) {
        BeginBlendMode(BLEND_ALPHA);
        rlSetTexture(GlowTex().id);
        rlBegin(RL_QUADS);
        for (int i = 0; i < 6; i++) {
            float ph = fmodf(t * 0.22f + i / 6.0f, 1.0f);
            Vector3 c = { g_houseExt.smoke.x + ph * 26.0f + sinf(t + i) * 3.0f, g_houseExt.smoke.y + 4 + ph * 70.0f, g_houseExt.smoke.z + ph * 10.0f };
            float r = 6.0f + ph * 16.0f;
            unsigned char a = (unsigned char)(110 * (1.0f - ph) * (ph < 0.1f ? ph * 10 : 1.0f));
            unsigned char v = (unsigned char)(170 - 60 * night);
            rlColor4ub(v, v, v, a);
            rlTexCoord2f(0, 0); rlVertex3f(c.x - r, c.y - r, c.z); rlTexCoord2f(1, 0); rlVertex3f(c.x + r, c.y - r, c.z);
            rlTexCoord2f(1, 1); rlVertex3f(c.x + r, c.y + r, c.z); rlTexCoord2f(0, 1); rlVertex3f(c.x - r, c.y + r, c.z);
            rlTexCoord2f(0, 0); rlVertex3f(c.x, c.y - r, c.z - r); rlTexCoord2f(1, 0); rlVertex3f(c.x, c.y - r, c.z + r);
            rlTexCoord2f(1, 1); rlVertex3f(c.x, c.y + r, c.z + r); rlTexCoord2f(0, 1); rlVertex3f(c.x, c.y + r, c.z - r);
        }
        rlEnd();
        rlSetTexture(0);
        EndBlendMode();
    }
    rlEnableDepthMask();
}

