    for (int i = 0; i < (int)g_assets.wildPropTex.size(); i++) if (g_assets.wildPropTexOk[i]) UnloadTexture(g_assets.wildPropTex[i]);
    for (int i = 0; i < 3; i++) if (g_assets.wildOreTexOk[i]) UnloadTexture(g_assets.wildOreTex[i]);
